/* English translations for openings, studies, Pattern Drill sets, and Threats sources. */
(function(){
"use strict";
const OPENINGS_EN = {"plans":{"e4e5":{"n":"Open Game","idea":"Both players staked a claim in the center with e4 and e5. Expect a fast fight for the center and rapid piece development.","w":["Quickly develop your knight to f3 and bishop (e.g. to c4 or b5).","Castle kingside and connect your rooks."],"b":["Defend the e5 pawn (usually with the knight to c6).","Develop your minor pieces and prepare to castle."]},"italian":{"n":"Italian Game","idea":"White aims the bishop on c4 straight at the weak f7 square next to Black's king.","w":["Prepare d4 with c3 (or play quietly with d3) and strike in the center.","Keep an eye on f7 – after castling you can also attack with a knight or rook via e1."],"b":["Develop the bishop to c5 or knight to f6 and castle quickly.","Guard the f7 square and the central d5 square."]},"evans":{"n":"Evans Gambit","idea":"White sacrifices a pawn on b4 to gain time for c3 and d4 and launch a fast attack on the king.","w":["Play c3 and d4 quickly, open the center, and attack the uncastled king.","Don't let Black finish development in peace."],"b":["If you take the pawn, develop fast and give it back at the right moment for king safety.","Play ...Bb6 or ...Ba5 and prepare to castle."]},"twoknights":{"n":"Two Knights Defense","idea":"Instead of ...Bc5, Black immediately attacks the e4 pawn with the knight on f6. Play often gets very sharp.","w":["You can play calmly with d3 and castle, or sharply with Ng5 targeting f7.","With Ng5, be ready for ...d5 and ...Na5."],"b":["After Ng5, answer with ...d5 (not ...Nxe4? or careless moves that ignore f7).","If White plays d3, calmly develop your bishop and castle."]},"spanish":{"n":"Ruy Lopez (Spanish Game)","idea":"White's bishop on b5 puts pressure on the c6 knight that defends e5, building long-term central pressure.","w":["Castle, play Re1, c3, and d4, and take over the center.","After ...a6, tuck the bishop back to a4 and later b3 or c2."],"b":["Chase the bishop with ...a6, develop the knight to f6 and bishop to e7.","Prepare to castle and firmly defend the e5 pawn."]},"scotch":{"n":"Scotch Game","idea":"White opens the center right away on move 3 with d4. Fast, open play with no waiting around.","w":["Open the center, bring pieces into the middle, and attack the king.","After ...Bc5 or ...Nf6, place your bishops and knights actively."],"b":["Capture on d4 and develop actively (...Bc5, ...Nf6).","Don't let White grab a ton of space for free."]},"fourknights":{"n":"Four Knights Game","idea":"Both players develop both knights first. A solid, calm, and safe opening.","w":["Finish development with the bishops (Bb5 or Bc4), castle, and open the center with d4.","Look for small improvements in piece placement."],"b":["Develop your bishops (...Bb4 or ...Bc5) and castle.","Keep the balance in the center of the board."]},"petrov":{"n":"Petrov's Defense (Russian Game)","idea":"Instead of defending e5, Black immediately counterattacks White's e4 pawn.","w":["Take on e5, retreat Nf3 after ...d6, and play d4 for a nice center.","Watch for the trap: after Nxe5 Nxe4?? Qe2! wins a piece."],"b":["After Nxe5, first kick the knight with ...d6 before taking on e4.","Develop your pieces quickly and castle."]},"philidor":{"n":"Philidor Defense","idea":"Black defends e5 with the d6 pawn. It's solid, but Black's f8 bishop has less room.","w":["Play d4 and Bc4 to gain space in the center and develop fast.","Press in the center and use your freer pieces."],"b":["Keep a solid center on e5, develop knights to f6 and d7, and prepare to castle.","Don't open the position before your king is safe."]},"vienna":{"n":"Vienna Game","idea":"White guards e4 with the c3 knight, keeping the f-pawn free for an attack with f4 or Bc4.","w":["Develop the bishop to c4 and prepare f4 on the kingside when the moment is right.","Play actively against f7."],"b":["The best counter is ...Nf6 and a timely central break with ...d5.","Don't give White a comfortable kingside attack."]},"kingsgambit":{"n":"King's Gambit","idea":"White sacrifices the f4 pawn to open the f-file for the rook and dominate the center with d4.","w":["Play Nf3, Bc4, and d4 and attack fast down the open f-file.","Don't allow Black a nasty queen check on h4."],"b":["Watch out for checks and attacks on f7 – either take the pawn and develop fast, or play ...d5.","Keep your king safe and don't fall behind in development."]},"center":{"n":"Center Game","idea":"White opens the center on move 2 with d4. After ...exd4, White often recaptures with the queen or gambits a pawn.","w":["Develop rapidly (Bc4, Nf3), and if your queen is on d4, watch out for losing time to ...Nc6.","In the Danish Gambit, aim both bishops at the kingside."],"b":["Take on d4 and gain time by attacking White's queen (...Nc6) while developing quickly.","Give back a pawn if it buys you safety and a lead in development."]},"bishop":{"n":"Bishop's Opening","idea":"White aims the bishop at c4 right away, targeting f7. Often transposes into the Italian or Vienna Game.","w":["Target f7, develop your knights, and prepare a central push or f4.","Keep your pieces active."],"b":["Play ...Nf6 or ...Bc5 and strike in the center with ...d5 at the right time.","Stay alert to early attacks on f7."]},"sicilian":{"n":"Sicilian Defense","idea":"The most fighting answer to 1. e4! Black fights for d4 from the flank, creating unbalanced and sharp play.","w":["In the Open Sicilian (Nf3 and d4), grab space, develop fast, and attack the king.","With queenside castling (O-O-O), launch a kingside pawn storm."],"b":["Use the half-open c-file for your rook and attack on the queenside.","Play ...d5 at the right moment to equalize the center."]},"french":{"n":"French Defense","idea":"Black prepares ...d5 with ...e6. A sturdy fortress, though Black's light-squared bishop on c8 starts out hemmed in.","w":["Claim the center (d4) and attack on the kingside or use your extra space.","Protect your d4 pawn from Black's pressure."],"b":["Attack White's center with ...c5 and ...Nc6 (and sometimes ...f6).","Look for a way to bring the c8 bishop into the game."]},"carokann":{"n":"Caro-Kann Defense","idea":"Black prepares ...d5 with ...c6. A very solid defense that doesn't block in the c8 bishop.","w":["Gain central space (d4, e5, or Nc3) and look for a kingside attack.","Don't let Black easily trade off all passive pieces."],"b":["Develop the light-squared bishop to f5 or g4 before playing ...e6.","Then back up the center solidly with ...e6 and ...c5."]},"scandinavian":{"n":"Scandinavian Defense","idea":"Black challenges White's e4 pawn right on move 1 with ...d5.","w":["After exd5 Qxd5, develop the knight to c3 attacking the queen to gain a lead in development.","Take over the center and attack while Black is still catching up."],"b":["If you recapture with the queen, retreat it to a safe square (a5, d6, or d8) after Nc3.","Finish development (...c6, ...Nf6, ...Bf5/Bg4) and castle."]},"pirc":{"n":"Pirc / Modern Defense","idea":"Black lets White occupy the center first and fianchettoes the bishop on g7 to snipe at the center from afar.","w":["Build a strong center (e4, d4), develop your pieces, and prepare a kingside attack.","Watch out for counterstrikes with ...c5 or ...e5."],"b":["Put the bishop on g7, castle, and then strike White's center with ...c5 or ...e5.","Let White overextend, then tear the center apart."]},"alekhine":{"n":"Alekhine's Defense","idea":"Black lures White's pawns forward by attacking e4 on move 1 with ...Nf6.","w":["Advance your pawns sensibly (e5, d4), but be careful not to let your center crumble.","Develop your pieces right behind your pawns."],"b":["Once White's pawns advance too far, attack them with ...d6 and ...c5.","Break down White's center before it squeezes you."]},"d4d5":{"n":"Closed Game","idea":"Both players occupy the center with d4 and d5. Play is calmer and more positional – good piece placement matters most.","w":["Add pressure to d5 with c4 (Queen's Gambit) or set up solidly with Bf4/e3.","Fight for control of e4 and c5."],"b":["Hold the center firmly on d5 (with ...e6 or ...c6).","Develop your pieces and don't forget the c8 bishop."]},"qg":{"n":"Queen's Gambit","idea":"White offers the c4 pawn to challenge Black's d5 pawn and win the center. (It's not a real sacrifice – White can easily win the pawn back.)","w":["Press against d5, develop knights to c3 and f3, and prepare e4 in the center.","Use the half-open c-file for your rook."],"b":["Defend d5 with ...e6 or ...c6, or take the pawn (...dxc4) and develop quickly.","Counterstrike with ...c5 or ...e5 at the right time."]},"qgd":{"n":"Queen's Gambit Declined","idea":"Black holds the d5 center firmly with ...e6. A rock-solid setup, though the c8 bishop needs time to get out.","w":["Develop the bishop to g5 or f4, castle, and prepare pressure on the queenside or center.","Make use of your extra space."],"b":["Castle and free your position with ...c5 or ...b6 and ...Bb7.","Defend the center patiently and wait for your counterplay."]},"qga":{"n":"Queen's Gambit Accepted","idea":"Black captures on c4 to release central tension, without trying to cling to the extra pawn at all costs.","w":["Play e3 or e4 and win the pawn back with Bxc4 while building a strong center.","Develop your pieces quickly and castle."],"b":["Don't desperately defend c4 with ...b5? (a4! breaks it apart).","Instead, develop fast (...Nf6, ...e6, ...c5) and strike White's center."]},"slav":{"n":"Slav Defense","idea":"Black defends d5 with c6 so the light-squared c8 bishop stays free. Solid and flexible.","w":["Develop knights to f3 and c3, play e3 or Bf4, and fight for the center.","Control the e5 square."],"b":["Develop the bishop to f5 or g4 before playing ...e6.","Then play ...e6 and at the right moment ...c5 or ...dxc4 with ...b5."]},"london":{"n":"London System","idea":"White builds a sturdy pawn pyramid (d4, e3, c3) and develops the bishop to f4 outside the chain. Simple and reliable.","w":["Set up Bf4, e3, c3, Nf3, Bd3, and Nbd2, then castle and aim for e5 or a kingside attack.","Watch out for an early ...c5 and ...Qb6 from Black."],"b":["Challenge White's center and queenside with ...c5 and ...Nc6 (often ...Qb6 too).","Don't let White peacefully build a kingside attack."]},"colle":{"n":"Colle System","idea":"White builds a solid d4, e3, Bd3, Nf3, c3 setup and aims to open the game later with the e4 break.","w":["Prepare e4 (with Bd3, Nbd2, Re1) and attack on the kingside once the center opens.","Play patiently and safely."],"b":["Prevent or meet the e4 break and develop actively (...c5, ...Nc6).","Take advantage of White's hemmed-in c1 bishop on the queenside."]},"trompowsky":{"n":"Trompowsky Attack","idea":"White attacks the f6 knight on move 2 with Bg5, aiming to double Black's pawns or take Black out of book.","w":["Decide whether to trade on f6 (doubling Black's pawns) or retreat to h4/f4.","Develop fast and fight for the center."],"b":["Respond actively (...Ne4, ...c5, or ...d5) instead of letting your structure be ruined easily.","Use the bishop pair if White takes on f6."]},"kid":{"n":"King's Indian Defense","idea":"A fierce fighting defense against 1. d4! Black lets White claim the center, puts the bishop on g7, castles, and then strikes back.","w":["Gain space on the queenside (c4, Nc3, b4–b5) and slow down Black's kingside attack.","Watch out for ...e5 or ...f5 breaks on the kingside."],"b":["After castling, prepare the ...e5 or ...c5 break.","If the center locks up, storm the kingside with ...f5, ...f4, and your pawns!"]},"grunfeld":{"n":"Grünfeld Defense","idea":"Black hands over the pawn center to bombard it with the g7 bishop and active pieces.","w":["Build a powerful pawn center (c4, d4, e4) and defend it from Black's piece pressure.","Don't let Black shatter your central pawns."],"b":["Fire at White's center with the g7 bishop and attack it with ...c5 and ...Nc6.","Play actively with your pieces."]},"nimzo":{"n":"Nimzo-Indian Defense","idea":"Black pins White's c3 knight with ...Bb4 and fights for control of the e4 square.","w":["Play for the bishop pair (Qc2 or e3), reinforce the center, and prepare e4.","Don't let Black blockade your pawns on c4."],"b":["Control e4, trade on c3 at the right moment, and target the doubled c4 pawn.","Stay flexible in the center (...d5 or ...c5)."]},"qid":{"n":"Queen's Indian Defense","idea":"Black fianchettoes the bishop on b7 to control the key e4 square from a distance.","w":["Claim central space with g3, Bg2, d5, or e4 and blunt the b7 bishop.","Castle and build pressure down the c-file."],"b":["Control e4 with the b7 bishop and f6 knight.","Prepare ...c5 or ...d5 to open the diagonal for the b7 bishop."]},"benoni":{"n":"Benoni Defense","idea":"Black immediately attacks d4 with ...c5, leading to unbalanced play: White attacks in the center, Black on the queenside.","w":["Push d5, claim space, and prepare the e4–e5 break in the center.","Keep an eye on Black's queenside pawn majority (...b5)."],"b":["Use your queenside pawn majority (...a6, ...b5) and the strong g7 bishop.","Put pressure on White's e4 pawn."]},"dutch":{"n":"Dutch Defense","idea":"Black fights for e4 with ...f5 – a sharp opening that slightly loosens the kingside.","w":["Play g3, Bg2, c4, and Nc3 and target Black's weak light squares.","Stay alert to Black's kingside attack."],"b":["Aim pieces at e4 (Bg7 or Be7, Nf6), castle, and attack on the kingside.","Reclaim control of the e4 square."]},"english":{"n":"English Opening","idea":"White starts with the flank move 1. c4, controlling d5 while keeping central options open.","w":["Often fianchetto the bishop on g2, put the knight on c3, and press on the queenside.","Control the key d5 square."],"b":["Answer with ...e5 (Reversed Sicilian), ...c5 (Symmetrical), or ...e6 with ...d5.","Fight for the central squares d4 and e4."]},"reti":{"n":"Réti Opening","idea":"White starts with Nf3 without revealing plans too soon, attacking the center from afar with g3 and Bg2.","w":["Place the bishop on g2, challenge the opponent's center with c4, and keep the position flexible.","Castle and adapt to what Black sets up."],"b":["Occupy the center with pawns (...d5, or ...c5 / ...e5) and develop calmly.","Don't let White easily undermine your center."]},"catalan":{"n":"Catalan Opening","idea":"Combines the Queen's Gambit (d4, c4) with a powerful bishop on g2 firing down the whole long diagonal.","w":["Use the g2 bishop to pressure Black's queenside and the d5 square.","Play patiently – even if you gambit the c4 pawn, you get huge pressure."],"b":["Defend the queenside solidly, develop quickly, and castle.","Look to free your game with ...c5 or ...dxc4."]},"bird":{"n":"Bird's Opening","idea":"White starts with 1. f4 to control e5, while taking care not to weaken the king too much.","w":["Control e5 (Nf3, e3/g3, b3, Bb2) and prepare a kingside attack.","Don't forget your own king's safety."],"b":["Play ...d5, ...g6, or the sharp From's Gambit (1...e5!).","Target the weakened e1–h4 diagonal."]},"polish":{"n":"Polish (Sokolsky) Opening","idea":"A rare and playful opening: 1. b4! White wants to put the bishop on b2 fast and surprise the opponent.","w":["Put the bishop on b2 and aim at the central e5 square and the kingside.","Watch the b4 pawn so Black doesn't win it for free."],"b":["Occupy the center (...e5, ...d5) and challenge the b4 pawn.","Calm development gives Black a very good game."]}},"book":["Open Game","Open Game (2. Nf3 Nc6)","Italian Game","Italian Game: Giuoco Piano","Italian Game: Classical Variation (c3)","Italian Game: Giuoco Pianissimo","Italian Game: Evans Gambit","Evans Gambit Accepted","Two Knights Defense","Two Knights Defense: Ng5 Attack on f7","Two Knights Defense: Modern Variation (d3)","Italian Game: Hungarian Defense","Ruy Lopez (Spanish Game)","Ruy Lopez: Morphy Defense","Ruy Lopez: Morphy Defense (3...a6 4. Ba4 Nf6)","Ruy Lopez: Closed Variation","Ruy Lopez: Exchange Variation","Ruy Lopez: Berlin Defense","Scotch Game","Scotch Game: Main Line","Scotch Gambit","Four Knights Game","Four Knights Game: Spanish Variation","Four Knights Game: Italian Variation","Petrov's Defense (Russian Game)","Petrov's Defense: Classical Variation","Philidor Defense","Philidor Defense: Main Line","Vienna Game","Vienna Game: Falkbeer Variation","Vienna Game: Bishop on c4","King's Gambit","King's Gambit Accepted","King's Gambit Declined (Classical)","King's Gambit: Falkbeer Countergambit","Center Game","Center Game: Queen on d4","Danish Gambit","Bishop's Opening","Sicilian Defense","Open Sicilian Defense","Sicilian Defense: Najdorf Variation","Sicilian Defense: Dragon Variation","Sicilian Defense: Scheveningen Variation","Sicilian Defense: Open with 2...Nc6","Sicilian Defense: with 2...e6","Sicilian Defense: Alapin Variation (c3)","Closed Sicilian Defense","Sicilian Defense: Bowdler Attack (Bc4)","French Defense","French Defense: Main Position","French Defense: Exchange Variation","French Defense: Advance Variation","French Defense: Tarrasch Variation","French Defense: Winawer Variation","French Defense: Classical Variation","Caro-Kann Defense","Caro-Kann Defense: Main Position","Caro-Kann: Exchange Variation","Caro-Kann: Advance Variation","Caro-Kann: Classical Variation","Scandinavian Defense","Scandinavian Defense: Queen Capture (2...Qxd5)","Scandinavian Defense: Modern Variation (2...Nf6)","Pirc Defense","Pirc Defense: Classical","Modern Defense","Alekhine's Defense","Alekhine's Defense: Main Line","Closed Game (1. d4 d5)","Queen's Gambit","Queen's Gambit Declined","Queen's Gambit Declined: with Bg5","Queen's Gambit Accepted","Slav Defense","Slav Defense: Main Line","Semi-Slav Defense","London System","London System (with Nf3)","London System","London System (vs ...Nf6)","Colle System","Trompowsky Attack","Indian Game (1. d4 Nf6)","King's Indian Defense","King's Indian Defense: Classical","Grünfeld Defense","Nimzo-Indian Defense","Queen's Indian Defense","Catalan Opening","Benoni Defense","Modern Benoni","Dutch Defense","Dutch Defense: Classical / Leningrad","English Opening","English Opening: Reversed Sicilian","English Opening: Symmetrical Variation","Réti Opening","Réti Opening: Main Line","Bird's Opening","Polish (Sokolsky) Opening"]};
const STUDIES_EN = {"evans":{"name":"Evans Gambit","intro":"The Evans Gambit is a brave opening in the Italian Game. White gives away a pawn and in return gets to develop pieces fast and build a strong center. In every chapter, you play as White and look for the right moves.","chapters":{"why":{"title":"Three Gifts for a Pawn","intro":"Captain Evans was a sailor. About 200 years ago, he invented this gambit. His idea: I will give my opponent a pawn and get three gifts in return. Try to find them!","moves":[{"q":"Which pawn can attack the bishop on c5, even though your opponent can capture it?","c":"4.b4! This is the Evans Gambit. White offers a pawn. It is not a mistake—it is a plan: the bishop that takes the pawn will soon have to run away."},{"c":"Black took the pawn. Black is up a pawn, but the bishop is standing on b4, where a pawn can attack it."},{"q":"Chase the bishop away with a pawn. That same pawn will also help with the move d4.","c":"5.c3! The first gift is TIME. White made a useful move. Black has to move that same bishop again and falls behind in bringing out the other pieces."},{"c":"The bishop retreated to a5. From there, it still eyes the c3 pawn and the king behind it."},{"q":"Put a second pawn in the center. The c3 pawn protects it.","c":"6.d4! The second gift is the CENTER. The pawns on e4 and d4 take away good squares from Black's pieces. White plays d4 right away, before Black has time to defend calmly with d6 and Bb6."},{"c":"Black captures the second pawn. Look at the c3 pawn: it cannot take back because the bishop on a5 would put the king in check. That is called a pin."},{"q":"The c3 pawn is pinned. Which move breaks the pin and hides your king at the same time?","c":"7.O-O! The king stepped off the diagonal, the pin is gone, and the rook joined the game. The third gift is OPEN LINES: your bishops and queen have clear paths to attack."}],"end":"The three gifts of the gambit: time, the center, and open lines. White is down two pawns, but all of White's pieces are getting ready to attack."},"main":{"title":"Main Line: Morozevich - Adams","intro":"Wijk aan Zee 2001. Two of the best players in the world are playing. Black defends as well as possible: instead of putting the knight on f6, Black puts it on e7 so the king can castle quickly. Watch how White makes things tricky.","moves":[{"c":"7...Ne7! On f6, a pawn could chase the knight with e5. From e7, there is no such threat and Black can castle right away."},{"q":"Black is getting ready to castle. Send a second attacker toward f7 so castling will not turn out well.","c":"8.Ng5! Both the knight and the bishop are aiming at f7. If Black castles now, Qh5 comes with a checkmate threat on h7 and a capture on f7. You will see how that goes in the chapter 'The Trap on f7'."},{"c":"8...d5! The best defense. The pawn steps into the path of the c4 bishop toward f7."},{"q":"The d5 pawn attacked your bishop. Capture it.","c":"9.exd5."},{"c":"9...Ne5. The knight jumped away from c6 because the d5 pawn was attacking it, and now it attacks the c4 bishop. If Black had taken 9...Nxd5?, then 10.Nxf7! Kxf7 11.Qf3+ would force the king out into the center."},{"q":"Your bishop is attacked by the knight. Tuck it away so it stays on the diagonal pointing at f7.","c":"10.Bb3! This is the move the book recommends. The bishop is safe, and as soon as the d5 pawn moves, it will aim at f7 again."},{"c":"10...O-O. Now Black can castle. Your own d5 pawn is standing in the way of the b3 bishop toward f7."},{"q":"Take the pawn back and attack the e5 knight at the same time.","c":"11.cxd4. The d4 pawn attacked the e5 knight, so the knight has to move again."},{"c":"11...Ng4. The knight jumped toward your king and eyes the f2 and h2 squares."},{"q":"Your knight is already aiming at f7. Bring your queen to aim there too.","c":"12.Qf3. The queen and the g5 knight both aim at f7. Do not rush with 12.Ba3 yet: Black would answer 12...Nxd5! and get a knight, a pawn, and fast development for the rook. Stockfish likes 12.Ne4 best here."},{"c":"12...Nf6!? The knight came back to defend the king and guard the h7 square."},{"q":"Bring out your last bishop. Which diagonal aims at Black's rook on f8?","c":"13.Ba3. The bishop aims right through the e7 knight toward the f8 rook. That means the e7 knight cannot move freely."},{"c":"13...h6. The pawn chases the g5 knight away."},{"q":"Your knight is attacked. Where should it jump so it stands in the center?","c":"14.Ne4. The knight steps into the center and offers a trade. After 14.Qe2?, Black would get the advantage with 14...Nfxd5."}],"end":"This is how grandmasters play the Evans Gambit. Stockfish thinks Black is a bit better here: Black has an extra pawn and defended well. Adams went on to win this game. That is why it is important to know the traps in the next chapters too: one slip by Black and White's attack comes roaring back. Remember White's plan: Ng5 toward f7, tuck the bishop on b3, capture on d4, and bring the queen into the attack."},"f7":{"title":"The Trap on f7: Jolowicz - Glunz","intro":"Hamburg 1971. This is the same position as in the main line, except Black castles too fast. Only the king was defending f7, and the king alone cannot hold it.","moves":[{"q":"The c4 bishop is already aiming at f7. Add a second attacker.","c":"8.Ng5! Both the knight and the bishop aim at f7."},{"c":"8...O-O? Black castles as if nothing is wrong. The right move was 8...d5, just like in the main line."},{"q":"The king hid in the corner. Bring a third piece that threatens both h7 and f7 at once.","c":"9.Qh5! Two threats at the same time: checkmate with Qxh7 and taking on f7 with Nxf7."},{"c":"9...h6. The pawn stops checkmate on h7 and attacks the knight."},{"q":"Checkmate on h7 is blocked, but f7 is not. Take there!","c":"10.Nxf7! The knight attacks the d8 queen and the h6 pawn."},{"c":"10...Rxf7. The rook captures the knight."},{"q":"Take the rook with check.","c":"11.Bxf7+. White gave up a knight and won a rook. Black's king has to move."},{"c":"11...Kh7."},{"q":"Take the pawn and open the path for your c1 bishop.","c":"12.cxd4. White owns the center and the c1 bishop can come out."},{"c":"12...Bb6. The bishop attacks the d4 pawn."},{"q":"Develop your bishop so it defends the d4 pawn.","c":"13.Bb2. The bishop sits on the long diagonal leading all the way to g7."},{"c":"13...Nxd4. Black captured the pawn, but now the b2 bishop aims straight at g7."},{"q":"Bring out your last knight. From there it can go to f3 next.","c":"14.Nd2."},{"c":"14...d6."},{"q":"Bring the knight closer to Black's king.","c":"15.Nf3. The knight attacks the d4 knight and gets ready to jump to g5."},{"c":"15...Ne2+. Check."},{"q":"Step aside with your king.","c":"16.Kh1."},{"c":"16...Nf4? The knight attacked the h5 queen. That is just what White was waiting for."},{"q":"Your queen is attacked, but there is an even stronger move: check with the knight!","c":"17.Ng5+! The h6 pawn cannot take the knight because that would open the queen's path to the king on h7."},{"c":"17...Kh8. The king runs into the corner."},{"q":"Checkmate in one move!","c":"18.Qxh6#! The g7 pawn cannot take the queen because the b2 bishop pins it to the king. The f7 bishop guards g8."}],"end":"Knight on g5, queen on h5, and bishop on f7. Three pieces attacking a king that castled too early."},"greedy":{"title":"Greedy Black: De Boer - Van der Kooij","intro":"Correspondence game, 1992. Black grabs a third pawn too. The book compares this to overeating: while Black keeps munching on pawns, White's pieces line up for the attack.","moves":[{"c":"7...dxc3? Black is three pawns ahead, but apart from the bishop and the c6 knight, all of Black's other pieces are still sitting at home."},{"q":"Put your queen behind the bishop so both aim at f7.","c":"8.Qb3! The queen and bishop aim at f7. Bxf7+ is a threat."},{"c":"8...Qf6. The queen defends f7."},{"q":"Chase the queen away with a pawn!","c":"9.e5! The pawn attacks the queen and White gains time."},{"c":"9...Qg6."},{"q":"Take the c3 pawn and bring out a piece at the same time.","c":"10.Nxc3. The knight enters the game. Almost all of White's pieces are developed, while Black only has the c6 knight and a bishop out."},{"c":"10...Nge7. Black wants to castle."},{"q":"Develop your last bishop onto the diagonal aiming at e7 and f8.","c":"11.Ba3! According to the book, this is a key position of the Evans Gambit and Black is in big trouble. The bishop aims through the e7 knight toward f8."},{"c":"11...O-O. The king tucked itself into the corner, but White's pieces will find a way to reach it."},{"q":"Put a rook on the open file.","c":"12.Rad1. The rook aims at the d7 pawn, so the c8 bishop cannot move."},{"c":"12...Re8."},{"q":"Attack Black's queen with your bishop.","c":"13.Bd3. The bishop attacks the queen on g6 and aims at h7. Stockfish would be even faster with 13.Ne4."},{"c":"13...Qh5."},{"q":"Send the knight closer to Black's king.","c":"14.Ne4. The knight eyes f6 and g5."},{"c":"14...Nxe5. Black grabbed yet another pawn."},{"q":"Trade knights.","c":"15.Nxe5."},{"c":"15...Qxe5."},{"q":"The queen is standing on the long diagonal. Attack it with your bishop.","c":"16.Bb2! The bishop attacked the queen and aims all the way to g7."},{"c":"16...Qe6."},{"q":"Attack the a5 bishop with your queen.","c":"17.Qb5. The queen attacks the a5 bishop and can swing over to h5 from there."},{"c":"17...Qb6. The queen defends the bishop."},{"q":"Now bring the queen over toward the king!","c":"18.Qh5. The queen and the d3 bishop both aim at h7."},{"c":"18...Ng6. The knight blocked the bishop's path to h7."},{"q":"Bring your knight into the attack too.","c":"19.Ng5. The knight attacks f7 and h7."},{"c":"19...h6. The pawn chases the knight away."},{"q":"Do not retreat! Sacrifice the knight on f7.","c":"20.Nxf7! The knight sacrificed itself to uncover Black's king."},{"c":"20...Kxf7."},{"q":"The king is out in the open. Attack Black's queen with your bishop.","c":"21.Bd4! The bishop attacks the b6 queen while Black's king stands exposed on f7."}],"end":"The game continued 21...c5 22.Bxc5 Qf6 23.Bc4+ Re6 24.Rd5, and Black resigned a few moves later. While Black was gobbling up pawns, White brought every piece into the fight."},"lasker":{"title":"The Careful Opponent: Grosar - Gross","intro":"Bukfurdo 1995. Black refuses to take on d4 and props up the e5 pawn with d6 instead. White finds another weak spot: the f8 square, which Black's king has to cross to castle.","moves":[{"c":"6...d6. The pawn holds e5 and opens the way for the c8 bishop."},{"q":"The c4 bishop aims at f7. Line up your queen behind it.","c":"7.Qb3! The queen and bishop stand in a line. That is called a battery. Bxf7+ is a threat."},{"c":"7...Qd7. The queen defends f7, but it stepped right in front of Black's own c8 bishop."},{"q":"Open up the center. Which pawn can you capture?","c":"8.dxe5."},{"c":"8...dxe5."},{"q":"Where can you put your c1 bishop so it stops Black's king from castling?","c":"9.Ba3! The bishop guards the f8 square. A king is not allowed to cross an attacked square when castling, so kingside castling is illegal right now."},{"c":"9...Bb6."},{"q":"Develop your knight. A pawn is on c3, so where should the knight go?","c":"10.Nbd2."},{"c":"10...Na5. The knight attacks both the b3 queen and the c4 bishop."},{"q":"Your queen is attacked. Move it onto the same diagonal where the a3 bishop stands.","c":"11.Qb4. The queen and bishop stand on the same diagonal and aim together at e7 and f8."},{"c":"11...c5!? The pawn chases the queen away."},{"q":"Step back with your queen. From where will it aim at the e5 pawn?","c":"12.Qb2. The queen looks all the way down the diagonal at e5."},{"c":"12...Nxc4. Black traded off your bishop."},{"q":"Take back.","c":"13.Nxc4. The knight attacks both the e5 pawn and the b6 bishop."},{"c":"13...Qe6? A mistake. The queen stops guarding the e5 pawn and sits on the e-file, where a rook can attack it later."},{"q":"The e5 pawn is undefended. Take it!","c":"14.Nfxe5. White won the pawn back and Black's king is still stuck in the center."},{"c":"14...Nf6. The knight attacks the e4 pawn."},{"q":"Give check with your queen.","c":"15.Qb5+. Check. Black has to block it."},{"c":"15...Bd7."},{"q":"Capture the bishop.","c":"16.Nxd7."},{"c":"16...Qxe4+. Black took a pawn with check."},{"q":"Your king has to move. Where to?","c":"17.Kd2. The king in the middle looks scary, but Black's attack will soon run out of steam."},{"c":"17...Qd5+."},{"q":"Move the king further to safety.","c":"18.Kc2."},{"c":"18...Qxd7. Black took the d7 knight. Both sides have the same number of pieces."},{"q":"Black's king still has not castled. Give check with a rook!","c":"19.Rhe1+. The rook came out onto the open file with check."},{"c":"19...Kf8."},{"q":"Take the pawn with check.","c":"20.Bxc5+."},{"c":"20...Bxc5."},{"q":"Take back, with check again.","c":"21.Qxc5+. White's pieces are much more active and Black's h8 rook is still trapped in the corner."}],"end":"White later traded queens and won the endgame with accurate play. It all started with Ba3: Black's king never made it to safety."},"laskertrap":{"title":"The 7...exd4? Trap: Alexander - Yates","intro":"Cambridge 1932. A careful opponent plays 6...d6 just like in 'The Careful Opponent'. This time, though, Black forgets about the queen + bishop battery and takes the d4 pawn.","moves":[{"c":"6...d6. The pawn holds e5."},{"q":"Put your queen behind the bishop so both aim at f7.","c":"7.Qb3! A battery aimed at f7. Bxf7+ is threatened."},{"c":"7...exd4?! Black takes the pawn and misses the threat. The right move was to guard f7 with 7...Qd7."},{"q":"Nobody is guarding f7. Take it with check!","c":"8.Bxf7+! The bishop captures with check. Black's king will never be able to castle now."},{"c":"8...Ke7. The king stays in the middle. On f8 it would have been a bit safer."},{"q":"The king is sitting in the center. Open a path toward it with a pawn!","c":"9.e5! The pawn attacks d6 and opens lines toward Black's king."},{"c":"9...dxe5?! Black took the pawn, but opened both the e-file and the d-file. 9...Nxe5 was better."},{"q":"The center is open. What should you do before you attack?","c":"10.O-O. Your king is safe and the f1 rook will join the attack."},{"c":"10...Bg4. The bishop pinned or attacked the f3 knight."},{"q":"Put a rook on the file where Black's king is standing.","c":"11.Re1! The rook aims right through the e5 pawn at the king on e7. White has a huge advantage."}],"end":"When a queen and bishop both aim at f7, the opponent must not forget about Bxf7+. A king left in the middle becomes a target."},"bc5":{"title":"The 5...Bc5 Retreat: Salygo - Boshoer","intro":"Correspondence game 1971. After 5...Bc5 6.d4 exd4 7.O-O d6 8.cxd4 Bb6, we reach a position that people have called the Normal Position of the Evans Gambit for 150 years. White has two plans here. In this game, you will see the d5 plan and a lovely knight sacrifice.","moves":[{"q":"The Normal Position. Push the d4 pawn forward to attack the c6 knight.","c":"9.d5! The pawn chases the knight away and takes away the c6 and e6 squares from Black's pieces."},{"c":"9...Na5. The knight goes to the edge and aims at the c4 bishop."},{"q":"Your c4 bishop is attacked. First, though, develop the c1 bishop onto the long diagonal.","c":"10.Bb2. The bishop aims all the way across the board to g7. If Black takes the bishop with 10...Nxc4, White wins a piece back with the fork 11.Qa4+."},{"c":"10...Ne7."},{"q":"Now move the c4 bishop back. Which square aims toward the kingside?","c":"11.Bd3. The bishop aims at h7, right where Black's king plans to hide."},{"c":"11...O-O."},{"q":"Develop your b1 knight.","c":"12.Nc3."},{"c":"12...Ng6."},{"q":"This knight is heading over to the kingside. Where is its first stop?","c":"13.Ne2. The knight heads toward Black's king and clears the way for the b2 bishop."},{"c":"13...c5. Black's pawn guards the d4 square."},{"q":"Put a rook on the c-file.","c":"14.Rc1. The rook waits behind the pawns for the c-file to open."},{"c":"14...Rb8."},{"q":"Salygo decides to attack. Which pawn opens the diagonal for the b2 bishop?","c":"15.e5!? A brave move. The pawn opens the b2 bishop's diagonal and pushes Black's pieces away from the king. Stockfish would play more calmly with 15.Nd2 and rates the position about equal."},{"c":"15...Bc7."},{"q":"The knight comes back. From where can it jump to e4 next?","c":"16.Nc3. The knight is aiming for e4 and from there toward Black's king."},{"c":"16...a6? Black wastes time on the queenside."},{"q":"Jump with your knight into the center, closer to the king.","c":"17.Ne4! The knight aims at f6 and d6."},{"c":"17...b6? Another slow move. Black needed to take the pawn with 17...Nxe5."},{"q":"Bring the second knight into the attack too.","c":"18.Nfg5. Both knights are standing right near Black's king. Stockfish would already sacrifice with 18.Nf6+!"},{"c":"18...h6? The pawn chases the knight, but weakens the king."},{"q":"Sacrifice the knight with check on f6!","c":"19.Nf6+! If the g7 pawn takes it, the king loses its shield."},{"c":"19...gxf6."},{"q":"Capture with the pawn!","c":"20.exf6! The f6 pawn sticks right beside the king like a wedge, and the queen is getting ready to go to h5. White has a winning attack and won the game."}],"end":"The d5 plan: chase the knight off c6, put the bishops on b2 and d3, and bring the knights over to the king. Once everything is ready, the Nf6+ sacrifice breaks the door open."},"be7":{"title":"The 5...Be7 Retreat: Kasparov - Anand","intro":"Riga 1995. The bishop hides on e7, close to the king. That is how Viswanathan Anand played against World Champion Garry Kasparov. Kasparov came up with two fresh ideas and won in 25 moves.","moves":[{"c":"5...Be7. A safe retreat. Black is ready to give the pawn back if it buys peace and quiet."},{"q":"The plan stays the same. What does White play after c3?","c":"6.d4. The center! dxe5 is a threat."},{"c":"6...Na5. The knight attacks the c4 bishop and wants to trade it off. However, it stands on the edge of the board."},{"q":"Do not let Black trade your bishop. Step back so the bishop does not block your queen on the d-file.","c":"7.Be2! Kasparov's move. The bishop avoids the trade and the d-file stays open for the queen. Now the knight on a5 has nothing to do."},{"c":"Black takes the pawn."},{"q":"Take back with a piece that attacks something right away. Look at the g7 pawn.","c":"8.Qxd4! The queen sits in the center and attacks the g7 pawn. Usually the queen should not come out early, but here nobody can chase it away because the knight is far away on a5."},{"c":"8...Nf6. The knight blocks the path to g7 and attacks the e4 pawn."},{"q":"Chase the knight away with a pawn.","c":"9.e5! Gaining time. The knight is attacked."},{"c":"9...Nc6. The knight comes back from the edge and attacks the queen."},{"q":"Your queen is attacked. Move it over to the kingside, where it can attack.","c":"10.Qh4. The queen switches to the kingside. The e5 pawn is still attacking the f6 knight."},{"c":"The knight escaped into the center."},{"q":"Attack the g7 pawn again.","c":"11.Qg3! The queen attacks g7. If Black castles, Bh6 comes with a checkmate threat on g7."},{"c":"11...g6. The pawn blocked the queen's path to g7, but it left dark-square holes around the king on f6 and h6."},{"q":"The attack can wait. What does your king still need?","c":"12.O-O. The e5 pawn squeezes the opponent and Black's king has no safe home."},{"c":"12...Nb6. The knight retreated."},{"q":"Take away the d5 square from the knight with a pawn.","c":"13.c4. The knight can never return to d5, and the e5 pawn is strong."},{"c":"13...d6. Black attacks the e5 pawn."},{"q":"Put a rook on the d-file, facing the d6 pawn.","c":"14.Rd1. The rook presses against d6 and controls the d-file."},{"c":"14...Nd7? Black wants to capture on e5. Castling with 14...O-O was better."},{"q":"Black's king is getting ready to castle. Which bishop stops it?","c":"15.Bh6! Kasparov's second idea. The bishop guards the f8 square, so Black's king cannot castle kingside."},{"c":"15...Ncxe5. Black captures the pawn."},{"q":"Trade knights.","c":"16.Nxe5."},{"c":"16...Nxe5."},{"q":"Develop your last knight.","c":"17.Nc3. All of White's pieces are in the game and Black's king is still stuck in the center."},{"c":"17...f6."},{"q":"Open up the game with the c4 pawn!","c":"18.c5! The pawn attacks d6 and opens paths toward Black's king. Kasparov won a few moves later."}],"end":"Kasparov's two ideas: the bishop on e2 so the a5 knight has nothing to trade, and the bishop on h6 so the king cannot castle."},"declined":{"title":"Gambit Declined: Stevic - Rogic","intro":"Vinkovci 1995. Some opponents get scared and do not take the pawn. No problem! The b4 pawn gained space, and another pawn goes hunting for the bishop.","moves":[{"c":"4...Bb6. Black turned down the gift."},{"q":"The b6 bishop does not have many free squares. Which pawn goes to catch it?","c":"5.a4! a5 is a threat. The bishop would have nowhere to run: on c5 the b4 pawn takes it, and on d4 the f3 knight takes it. It would be trapped!"},{"c":"5...a6. Black made an escape square for the bishop on a7."},{"q":"Develop your knight so it can jump to d5 next.","c":"6.Nc3. The knight joins the game and gets ready to hop into the center."},{"c":"Black develops a knight."},{"q":"Jump into the center with your knight. Who do you attack there?","c":"7.Nd5! The knight attacks both the b6 bishop and the f6 knight."},{"c":"Black trades off the knight."},{"q":"Take back with a pawn that attacks the knight.","c":"8.exd5. The pawn attacks the c6 knight, which has to move again. Another gain of time!"},{"c":"The knight jumped into the center."},{"q":"The knight jumped into the center. First, put your king in safety.","c":"9.O-O. Stockfish would play the bolder 9.d6 here, but castling is good too."},{"c":"9...Nxf3+. Black traded the knight."},{"q":"Take back.","c":"10.Qxf3."},{"c":"10...d6."},{"q":"Remember the plan. Which pawn chases the bishop?","c":"11.a5! The bishop has to hide in the corner on a7."},{"c":"11...Ba7."},{"q":"Develop your bishop onto the long diagonal.","c":"12.Bb2. The bishop aims at e5 and g7."},{"c":"12...O-O?! Black castles, but now comes a strike in the center."},{"q":"Strike in the center!","c":"13.d4! The pawn attacks e5. The a7 bishop hits the d4 pawn like a brick wall."}],"end":"Even when the opponent turns down the gambit, White chases the bishop with pawns and builds the center. Black's bishop ends up stuck in the corner on a7."},"nge7":{"title":"Human vs. Computer: 10...dxc3?!","intro":"The Hague 1992. Famous master David Bronstein plays against a computer. You know this position from the main line, but the computer grabs another pawn here. The book compares that to dancing in a minefield with your eyes closed.","moves":[{"c":"10...dxc3?! Back then, computers loved grabbing pawns and did not think much about king safety."},{"q":"The e5 knight stands on the open e-file. Attack it with your queen.","c":"11.Qe2. The queen attacks the e5 knight and stands on the same file as Black's king."},{"c":"11...f6. The pawn defends the e5 knight and attacks your g5 knight."},{"q":"Your g5 knight is attacked. Jump with it into the center.","c":"12.Ne4. The knight eyes the d6 and f6 squares near Black's king."},{"c":"12...Nxd5. The computer grabs another pawn."},{"q":"Develop your c1 bishop so Black's king cannot castle.","c":"13.Ba3! The bishop guards the f8 square. Black's king will stay stuck in the center."},{"c":"13...c6. The pawn defends the d5 knight."},{"q":"Give check with your knight.","c":"14.Nd6+. The book marks this move as doubtful, but Stockfish thinks it is the very best move."},{"c":"14...Kd7. The king walks into the middle of the board."},{"q":"Attack the e5 knight with a pawn.","c":"15.f4. The pawn chases the e5 knight. Stockfish would capture right away with 15.Bxd5."},{"c":"15...Ng6."},{"q":"Take the d5 knight.","c":"16.Bxd5! If Black takes the bishop with 16...cxd5?, then 17.Qb5+ wins for White."},{"c":"16...Qb6+. Black throws in a check first."},{"q":"Step aside with your king.","c":"17.Kh1."},{"c":"17...cxd5. Now Black takes the bishop and is up a piece."},{"q":"Forget about material for a moment. Take the c3 pawn with your knight, even though the bishop can capture it.","c":"18.Nxc3!! If the bishop takes the knight, the b-file opens for your rook to attack the queen. The book says time matters more than material here. Stockfish would play even stronger with 18.Rd1. White is better even with fewer pieces: Black's king is stranded in the center with no defenders."}],"end":"The game continued 18...Bxc3 19.Rab1 and got wild, with mistakes from both sides. Later the computer blundered 24...Rh8?? and Bronstein won. The human won because he knew fast pieces and an exposed enemy king are worth more than pawns."},"c5std":{"title":"The 5...Bc5 Retreat: Chigorin - Steinitz","intro":"London 1883. Mikhail Chigorin plays against the first World Champion. The bishop goes back to c5 and White builds the center so that every move attacks something.","moves":[{"c":"5...Bc5. The bishop is back on c5."},{"q":"Attack the c5 bishop with a pawn and take over the center at the same time.","c":"6.d4! Another gain of time: the bishop is under attack."},{"c":"Black takes the pawn."},{"q":"Do not take back right away! What matters more than a pawn right now?","c":"7.O-O! King to safety first—the d4 pawn is not running away. After 7.cxd4, the bishop would check on b4 and you would have to deal with the check instead of attacking."},{"c":"7...d6. Black opens the path for the c8 bishop."},{"q":"Now take the pawn back and build your center.","c":"8.cxd4. The e4 and d4 pawns stand side by side and attack the c5 bishop again."},{"c":"8...Bb6. The Normal Position. In Salygo - Boshoer White played the d5 plan; here you will see the second plan."},{"q":"Develop another piece toward the center.","c":"9.Nc3! The knight gets ready to jump to d5. White has three pieces out and has castled, while Black only has two pieces out."},{"c":"9...Na5. The knight attacks the c4 bishop, but a knight on the rim is dim."},{"q":"Your c4 bishop is attacked, but you can attack first. Which piece can attack Black's queen?","c":"10.Bg5! An attack on the queen. Black has no time to take the c4 bishop and has to save the queen first."},{"c":"10...f6. The pawn chases the bishop, but it leaves a hole near Black's king, and pawns can never move backward."},{"q":"Step back with your bishop so it aims at the d6 pawn.","c":"11.Bf4. The bishop stepped back and eyes the d6 pawn."},{"c":"11...Nxc4. Black takes the bishop. It looks like White lost a piece, but..."},{"q":"Find a check that also attacks the c4 knight.","c":"12.Qa4+! A double attack: check to the king and an attack on the knight."},{"c":"Black blocks with the queen."},{"q":"Win your piece back.","c":"13.Qxc4. The piece is back. The queen guards the g8 square, so Black's king cannot castle kingside. White has a strong center and Black has to be super careful."},{"c":"13...Qf7?! The queen offers a queen trade. Black loses time with this."},{"q":"Jump into the center with your knight. What does it attack there?","c":"14.Nd5! The knight stands in the center and attacks the b6 bishop."},{"c":"14...g5. The pawn chases the f4 bishop."},{"q":"Step back with your bishop.","c":"15.Bg3."},{"c":"15...Be6. The bishop attacked the d5 knight, and your queen is standing right behind it."},{"q":"Move the queen out of danger with check!","c":"16.Qa4+! The queen stepped away and gave check."},{"c":"16...Bd7."},{"q":"Your queen is attacked. Move it so it aims at the d6 pawn.","c":"17.Qa3. The queen aims at the d6 pawn. Chigorin won this game."}],"end":"When you have the e4 + d4 center and faster development, look for moves that attack something. Then your opponent never gets time to castle."},"c5d3":{"title":"The d3 Pawn Trap: Ragozin - Ilyin-Zhenevsky","intro":"Moscow 1930. Black does not want White to build a center and pushes the pawn to d3. But Black forgot about the f7 square.","moves":[{"c":"7...d3?! The pawn pushes forward so White cannot play cxd4. Notice something: the c5 bishop has no defender. Keep that in mind!"},{"q":"Two attackers on f7! Which piece joins the c4 bishop?","c":"8.Ng5! Nxf7 is a threat, forking the queen and the rook."},{"c":"8...Nh6. The knight defends f7. Everything looks fine."},{"q":"A knight and the king defend f7. Capture there anyway! You will see why in a moment.","c":"9.Nxf7! The knight sacrifices itself to pull the defenders off their squares."},{"c":"Black takes the knight."},{"q":"Keep capturing and give check!","c":"10.Bxf7+! The king has to take and step out of its house."},{"c":"The king took the bishop. White gave up two pieces for one. So far..."},{"q":"The king is out in the open and the c5 bishop is undefended. Find a queen check that attacks the bishop too.","c":"11.Qh5+! A queen fork: check to the king and an attack on the c5 bishop."},{"c":"Black blocks with a pawn."},{"q":"Take the undefended piece.","c":"12.Qxc5. The pieces are even again. Black still has an extra pawn, but Black's king can never castle."},{"c":"12...d6. The pawn chases the queen away."},{"q":"Move your queen so it attacks the d3 pawn.","c":"13.Qe3. The queen attacks the d3 pawn."},{"c":"13...Qe7. Black offers a queen trade."},{"q":"Develop your knight. The d3 pawn will not escape.","c":"14.Nd2. The d3 pawn will fall soon and Black's king has no f7 pawn to hide behind. White is better."}],"end":"An undefended piece + a king pulled out into the open = look for a queen fork."},"be7k":{"title":"The 5...Be7 Retreat: Shirov - Timman","intro":"Biel 1995. You know the position after 8.Qxd4 from Kasparov - Anand. Here Timman plays differently: 8...d6, leaving the g7 pawn undefended. Alexei Shirov was famous for wild attacks.","moves":[{"c":"8...d6. Black wants a pawn in the center and does not mind if the queen takes g7."},{"q":"The g7 pawn is undefended. Grab it with your queen!","c":"9.Qxg7. A free pawn, and the queen attacks the h8 rook."},{"c":"9...Bf6. The bishop chases the queen away."},{"q":"Step back with your queen, but stay near the kingside.","c":"10.Qg3."},{"c":"10...Qe7. The queen attacks the e4 pawn."},{"q":"King to safety.","c":"11.O-O. The book recommends 11.Ng5 here, while Stockfish slightly prefers castling."},{"c":"11...Bd7."},{"q":"Your f3 knight can jump into the center. Where to?","c":"12.Nd4!? The knight steps into the center. However, the e4 pawn was left undefended and Black could have taken it with 12...Qxe4. Stockfish would rather develop the knight with 12.Nbd2."},{"c":"12...O-O-O?! Black castles on the queenside. Taking the e4 pawn was better."},{"q":"Develop your b1 knight.","c":"13.Nd2."},{"c":"13...Nc6."},{"q":"Black's king is on c8. Bring your queen closer to the queenside.","c":"14.Qe3. The queen aims at a7."},{"c":"14...h5."},{"q":"Put a rook on the open b-file, pointing toward the king.","c":"15.Rb1! The rook aims at b7."},{"c":"15...Nh6."},{"q":"Move the queen onto the diagonal leading to a6.","c":"16.Qd3!? The queen prepares to go to a6 and b5. Stockfish would trade knights first with 16.Nxc6."},{"c":"16...b6."},{"q":"Attack the king with a pawn!","c":"17.a4! The pawn races toward a5 to open the a-file."},{"c":"17...Kb8."},{"q":"Keep pushing!","c":"18.a5."},{"c":"18...Nxa5. Black captured the pawn."},{"q":"The queen charges toward the king. Where to?","c":"19.Qa6. The queen stands right near Black's king and eyes a7 and b7."},{"c":"19...Ka8? A mistake. 19...Nc6 was better."},{"q":"Open the long diagonal for your e2 bishop!","c":"20.e5! The pawn cleared the e4 square. When the bishop jumps to f3, it will aim all the way to a8, where the king is standing. Stockfish would play even stronger with 20.Nb5."},{"c":"20...Qxe5? Black captures and opens the diagonal completely. Taking with the bishop, 20...Bxe5, was better."},{"q":"Give check with your bishop along the long diagonal!","c":"21.Bf3+. Check on a8."},{"c":"21...d5. The pawn blocked the check."},{"q":"Attack the e5 queen and the a5 knight at the same time with your knight.","c":"22.Nc4! The knight attacks both the queen and the a5 knight."},{"c":"22...Bc8. The bishop attacked the a6 queen."},{"q":"Your queen is attacked. Move it away by capturing something!","c":"23.Qxa5! The queen captured the knight. If Black takes with 23...bxa5?, then 24.Nxe5 wins. Shirov won the game."}],"end":"When Black's king castles queenside, White attacks with pawns and down the long diagonal toward a8."},"decla5":{"title":"Watch Out, Trap for White! Kasparov - Piket","intro":"In the Gambit Declined chapter, Black let your pawn march all the way to a5. Here Black stops it with a5. There is a trap waiting for WHITE. A good attacker also knows when NOT to take. Here is how Kasparov played against Piket.","moves":[{"c":"5...a5. Now the a4 pawn cannot go any further."},{"q":"Your b4 pawn is attacked. Push it so it chases the knight.","c":"6.b5. The pawn attacks the c6 knight, which was defending the e5 pawn."},{"c":"6...Nd4. The knight jumped into the center and left the e5 pawn undefended. It is bait!"},{"q":"WATCH OUT, trap! The e5 pawn is poisoned. Trade off the strong knight in the center instead.","c":"7.Nxd4! Correct. After the greedy 7.Nxe5?, Black plays Qg5! attacking both the knight and the g2 pawn. And after 8.Nxf7 Qxg2 9.Rf1 Qxe4+ 10.Be2, Black's knight gives checkmate on f3!"},{"c":"The bishop takes back and stands in the center."},{"q":"Chase the bishop away with the pawn that prepares d4.","c":"8.c3. A gain of time. The bishop has to retreat."},{"c":"The bishop goes back to b6."},{"q":"Now build the center.","c":"9.d4! White has a strong center, did not even have to give up a pawn, and the b6 bishop is blocked by your pawns."},{"c":"9...exd4?! Black takes and opens the game. That helps whoever has better development."},{"q":"First, get your king to safety.","c":"10.O-O."},{"c":"10...Ne7."},{"q":"Attack the e7 knight with your bishop.","c":"11.Bg5."},{"c":"11...h6."},{"q":"Trade your bishop for the knight.","c":"12.Bxe7. Black has to recapture with the queen."},{"c":"12...Qxe7."},{"q":"Take the pawn back.","c":"13.cxd4. White has two pawns in the center."},{"c":"13...Qd6? The queen attacks the d4 pawn."},{"q":"Leave the d4 pawn alone and develop your knight!","c":"14.Nc3! If Black takes on d4, the knight will jump to d5."},{"c":"14...Bxd4. Black took the pawn and attacked the a1 rook."},{"q":"Jump into the center with your knight!","c":"15.Nd5! The a1 rook will fall, but White gets a huge attack for it: the d5 knight and c4 bishop aim at the kingside, and Black's king still has not castled."},{"c":"15...Bxa1."},{"q":"Capture the bishop with your queen.","c":"16.Qxa1. The queen sits on the long diagonal aiming at g7."},{"c":"16...O-O? The king hid away, but White's attack is just getting started."},{"q":"Chase the queen away with a pawn!","c":"17.e5! The queen has to move and the long diagonal opens up."},{"c":"17...Qc5."},{"q":"Bring your rook into the game and attack the queen.","c":"18.Rc1! The rook attacks the c5 queen and the c7 pawn."},{"c":"18...c6."},{"q":"Your c4 bishop is attacked. Hide it, while keeping it aimed at f7.","c":"19.Ba2. The bishop aims at f7."},{"c":"19...Qa3."},{"q":"Attack the a8 rook with your knight.","c":"20.Nb6! The knight attacks the a8 rook. Kasparov took it a move later and won the game."}],"end":"Before you grab a free pawn, ask yourself: what did my opponent set up for me? And when the opponent opens the game, quickly developed pieces win."},"qearly":{"title":"The Queen Came Out Too Early: Chigorin - Steinitz","intro":"Telegraph Match 1891. The first World Champion, Steinitz, brings his queen out on move six. The book jokes that this move should not even be shown to kids! You will see why.","moves":[{"q":"King to safety while your opponent is not threatening anything.","c":"6.O-O. White castles first; d4 will come in a moment."},{"c":"6...Qf6?! The queen came out too early. It eyes f2, but White's pieces will chase it around."},{"q":"Strike in the center.","c":"7.d4! White owns the center."},{"c":"7...Nh6. The knight guards the f7 square."},{"q":"Attack the queen with your bishop!","c":"8.Bg5! Gaining time. The queen has to move again."},{"c":"8...Qd6?! The queen goes to the center, where it will soon be attacked again."},{"q":"Chase the c6 knight away with a pawn.","c":"9.d5. The knight has to retreat and Black's pieces get in each other's way."},{"c":"9...Nd8."},{"q":"Attack the a5 bishop with your queen.","c":"10.Qa4. The queen attacks the a5 bishop."},{"c":"10...Bb6."},{"q":"Develop your knight. A pawn is on c3. From where can the knight jump to c4?","c":"11.Na3. The knight heads for c4, where it will attack the d6 queen."},{"c":"11...c6?!"},{"q":"The c4 bishop is in the knight's way. Clear the square.","c":"12.Be2. The c4 square is free for the knight."},{"c":"12...Bc7."},{"q":"Jump with your knight to c4 and attack the queen.","c":"13.Nc4. The queen has now been attacked three times!"},{"c":"13...Qf8. The queen went all the way back home. Black lost tons of time."},{"q":"Push the pawn and open the way for your knight to b6!","c":"14.d6! A pawn sacrifice. When the bishop takes it, the knight jumps to b6."},{"c":"14...Bxd6."},{"q":"Jump with your knight to b6 and attack the a8 rook.","c":"15.Nb6! The knight attacks the a8 rook and traps the c8 bishop inside."},{"c":"15...Rb8."},{"q":"Take the a7 pawn with your queen.","c":"16.Qxa7. The queen broke into Black's camp and Black's pieces cannot move. Chigorin won."}],"end":"A queen that comes out too early becomes a target. White attacked it three times while developing every piece."},"shab":{"title":"Attack on the King: Chigorin - Shabelsky","intro":"Correspondence game 1884. Black brings the knight to f6 and grabs the e4 pawn too. In return, White cooks up a strong attack on the king.","moves":[{"c":"6...Nf6."},{"q":"Strike in the center.","c":"7.d4."},{"c":"7...Nxe4. Black takes a second pawn."},{"q":"Capture the e5 pawn.","c":"8.dxe5. The book recommends 8.Nxe5!, which gives White an even better game. In the actual game, though, this move worked well for Chigorin too."},{"c":"8...O-O."},{"q":"Attack the e4 knight with your bishop.","c":"9.Bd5. The bishop attacks the e4 knight."},{"c":"9...Nc5."},{"q":"Send your knight toward the king.","c":"10.Ng5! The knight eyes h7 and f7."},{"c":"10...Ne6? Black wants to trade knights, but loses time. 10...Qe7 was right."},{"q":"Bring in the queen. Which square will it aim at together with the knight?","c":"11.Qh5! Threatening checkmate with Qxh7."},{"c":"11...Nxg5."},{"q":"Take back with the bishop.","c":"12.Bxg5. The bishop attacks the d8 queen."},{"c":"12...Qe8."},{"q":"Park your bishop right in front of Black's king!","c":"13.Bf6! White threatens to bring the queen to g5 or h6 and give checkmate on g7. If Black takes the bishop with 13...gxf6, then 14.Be4 wins for White."},{"c":"13...Ne7."},{"q":"Bring your last piece into the attack.","c":"14.Nd2. White has a big advantage and Chigorin won the game."}],"end":"Knight on g5, queen on h5, and bishop on f6: three pieces right next to the king. An attack like that is very hard to defend."},"evg1":{"title":"The Evergreen Game 1: The Setup","intro":"Berlin 1852. Adolf Anderssen, the greatest attacker of his time, plays the Evans Gambit against Dufresne. The game is so beautiful that it was named the Evergreen Game. You play Anderssen's moves.","moves":[{"c":"Dufresne captures the pawn."},{"q":"You know this one already: the c3 pawn is pinned. What do you play?","c":"7.O-O. The king is safe and the pin is broken."},{"c":"7...d3. Black pushes the pawn to stop White from building a center."},{"q":"Set up a battery aimed at the f7 square.","c":"8.Qb3! The queen and bishop aim at f7."},{"c":"8...Qf6. The queen defends f7."},{"q":"Chase the queen away with a pawn.","c":"9.e5! Gaining time. The knight cannot take the pawn: after 9...Nxe5?, the rook comes to e1 and the knight is pinned because the king is behind it."},{"c":"The queen retreated."},{"q":"Put a rook on the file where Black's king is standing.","c":"10.Re1. The rook faces the king. There are still pieces in between, but the file will open up one day."},{"c":"Black develops a knight and wants to castle."},{"q":"Develop your last bishop so it aims at the e7 knight.","c":"11.Ba3. The bishop aims at the e7 knight. Every White piece is pointing toward Black's king."},{"c":"11...b5?! Dufresne sacrifices a pawn himself to open the b-file for his rook."},{"q":"Take the pawn with your queen.","c":"12.Qxb5. A free pawn."},{"c":"The rook attacks the queen."},{"q":"Step back with your queen so it aims at the c6 knight and the king behind it.","c":"13.Qa4. The queen stands on the a4-e8 diagonal, right where Black's king is sitting. That will be important later!"},{"c":"The bishop steps back."},{"q":"One piece is still sleeping. Wake it up!","c":"14.Nbd2. Rule of attacking: bring all your pieces into the game before you strike."},{"c":"Black develops the bishop."},{"q":"Send your knight into the center, closer to the king.","c":"15.Ne4. The knight eyes the d6 and f6 squares right next to the king."},{"c":"15...Qf5? The queen attacks the knight, but it is a mistake. Black should have castled earlier."},{"q":"Take the pawn with your bishop and tuck it behind the knight.","c":"16.Bxd3. The bishop hides behind the knight. When the knight jumps away, the bishop will attack the queen. That is called a discovered attack."},{"c":"16...Qh5. The queen moved out of the way, but Black's king is still stuck in the center and never got to castle."},{"q":"Start the combination. Sacrifice the knight with check!","c":"17.Nf6+!? A daring sacrifice. Stockfish says 17.Ng3 won more simply, but Anderssen wanted a dazzling combination and opened the e-file for his rook."}],"end":"White has every piece in play and Black's king is stuck in the center. In the next chapter comes the famous combination."},"evg2":{"title":"The Evergreen Game 2: The Combination","intro":"Anderssen just sacrificed a knight. Now he is going to sacrifice a rook and a queen too, and give checkmate with two bishops! Try to find the moves just like him.","moves":[{"c":"Black takes the knight."},{"q":"Take back with the pawn. Which file opens up?","c":"18.exf6. The e-file is open! The e1 rook attacks the e7 knight, and the knight is pinned because the king is behind it."},{"c":"18...Rg8. Black attacks too! The rook and queen aim at the g2 pawn."},{"q":"Bring your last piece into play. Put it on the d-file.","c":"19.Rad1. A quiet move that prepares the combination and sets a trap too: Anderssen lets his opponent capture the f3 knight. Stockfish would play more carefully with 19.Be4."},{"c":"19...Qxf3? Dufresne takes the knight and threatens checkmate on g2. It is a mistake! Now White gives check after check and Black never gets another turn to attack."},{"q":"Your opponent threatens checkmate, so you have to keep giving check! What do you capture with on e7?","c":"20.Rxe7+! The rook sacrifices itself. If the c6 knight takes it, it clears the path for the queen to d7."},{"c":"The knight takes the rook. Running with the king to d8 would have lasted longer, though White would still win."},{"q":"The prettiest move of the game. Sacrifice your queen with check!","c":"21.Qxd7+!! The queen sacrifices itself. The king has to take and step onto the d-file, where the d1 rook is waiting."},{"c":"The king takes the queen."},{"q":"Move the bishop off the d-file so that it gives check too.","c":"22.Bf5+! Double check: both the f5 bishop and the d1 rook give check. Against a double check, the only choice is to run with the king."},{"c":"The king runs back."},{"q":"Drive the king into the corner with another bishop check.","c":"23.Bd7+. The d1 rook protects the bishop, so the king cannot take it."},{"c":"The king has only one legal square left."},{"q":"Checkmate in one move! Which bishop delivers it?","c":"24.Bxe7#! Two bishops and the f6 pawn trapped the king. White sacrificed a knight, a rook, and a queen—and won!"}],"end":"It all started with the gambit: time, the center, open lines, and an opponent's king left in the middle."}}},"friedliver":{"name":"Fried Liver Attack","intro":"After 3...Nf6, White can immediately attack Black's weakest square, f7, with 4.Ng5. You don't need to memorize moves by heart. In each chapter you'll learn WHY each piece goes where it goes: how to sacrifice a knight, how to chase the king in the center, and what to play when your opponent defends properly. Based on analysis by Richard Westbrook, all moves checked with Stockfish.","chapters":{"attack":{"title":"Attack on f7: 4.Ng5","intro":"White now breaks a rule: moving the same knight a second time. Famous master Tarrasch called it a 'duffer's move.' But this move attacks Black's weakest square, and Black has to come up with something right away.","moves":[{"q":"The c4 bishop is already aiming at f7. Which piece joins the attack?","c":"4.Ng5! Two pieces are attacking f7: the knight and the bishop. Only the king defends it. You're allowed to break the rule about moving the same piece twice when you make a serious threat."},{"c":"4...d5! The best defense. The pawn steps in the bishop's way and attacks it at the same time."},{"q":"The d5 pawn is attacking your bishop. What will you capture it with?","c":"5.exd5. You're up a pawn, and your pawn attacks the c6 knight."},{"c":"5...Nxd5? It looks natural — Black wins the pawn back. But only the queen defends the knight on d5. The right move was 5...Na5."},{"q":"Now comes a brave sacrifice. Where can the knight jump to attack both the queen and the rook?","c":"6.Nxf7! This is the Fried Liver Attack. The knight attacks both the queen and the rook, so the king has to capture it."},{"c":"6...Kxf7. Black is up a piece, but their king has stepped out of its safe house."},{"q":"Find a check with the queen so that two pieces attack the d5 knight.","c":"7.Qf3+! Check, and an attack on the d5 knight at the same time. The queen and bishop attack it, and only the queen defends it."},{"c":"7...Ke6. The only move that keeps the knight: the king comes out to defend it himself. Now he's standing right in the middle of the board."},{"q":"Two pieces attack the d5 knight and two defend it. Bring in a third attacker!","c":"8.Nc3! Three attackers, two defenders. Even worse for Black, the d5 knight can't run away: it's stuck between the c4 bishop and its own king — it's pinned."}],"end":"You gave up a knight for a pawn. But Black's king is stuck in the center and all your pieces are joining the attack. Over the board, this is super hard for Black to defend. In the next chapters, you'll see how to finish the attack."},"kg8":{"title":"The king hides the wrong way: checkmate!","intro":"Black's king just got checked by the queen. Lots of kids run straight back home with him. Show them that checkmate is waiting at home.","moves":[{"c":"7...Kg8?? The king hid in the corner. Now only the queen defends the d5 knight."},{"q":"Two pieces attack the d5 knight and only one defends it. Capture it with your queen with check!","c":"8.Qxd5+! Check, and the king has nowhere to run. Black has to take the queen."},{"c":"8...Qxd5. Queen takes queen."},{"q":"Take the queen back. With which piece so it's check again?","c":"9.Bxd5+. Check again! The king still has no free squares — Black can only block the check."},{"c":"9...Be6. The bishop steps in between. Black has nothing else left."},{"q":"Finish it off. Checkmate in one move!","c":"10.Bxe6 mate! The king is trapped by his own pieces: the f8 bishop, the h8 rook, and the g7 and h7 pawns."}],"end":"After 7.Qf3+, Black has only one good move: 7...Ke6. Even 7...Ke8 loses: you play 8.Bxd5, you're two pawns up, and Black's king can never castle."},"nce7":{"title":"Most common defense 8...Ne7: open the center","intro":"Black needs another defender for the d5 knight. Most often the c6 knight moves back to e7. Your plan: open the center where Black's king is standing and bring your rooks there.","moves":[{"c":"8...Ne7. Three pieces defend the d5 knight now: the king, the queen, and the e7 knight."},{"q":"Black's king is hiding behind the e5 pawn. Which pawn attacks that wall?","c":"9.d4! The pawn attacks e5 and opens the path for the c1 bishop. Always open files against a king in the center."},{"c":"9...c6. One more defender for the d5 knight. Still, Black hasn't developed any bishops or rooks."},{"q":"You need your rooks in the attack too. Which move tucks your king away and brings a rook into the game?","c":"10.O-O! Your king is safe and a rook is ready to come to the e-file or d-file, straight toward Black's king."},{"c":"10...Ng6? The knight guards the e5 pawn and clears the way for the f8 bishop. It looks sensible, but the computer says the king should have stepped back to d7 instead. Now you open the center."},{"q":"Open the d-file. Take the pawn!","c":"11.dxe5. The d-file is open! When a rook lands on it, four pieces will be attacking the d5 knight."},{"c":"11...Bc5. Black finally brings out a bishop. They skipped taking the e5 pawn. You'll see why in the next chapter."},{"q":"Three pieces attack the d5 knight. Add a fourth attacker along the open file.","c":"12.Rd1! The rook attacks the d5 knight, and Black's queen is standing right behind it."},{"c":"12...Nge7. The knight goes back to defend d5. You kept your e5 pawn."},{"q":"Nothing is defending the c5 bishop. Attack it with a knight from the center.","c":"13.Ne4! The knight attacks the c5 bishop and also eyes the g5 square, where it could give check."}],"end":"For your knight, you have two pawns and an attack that never stops. Black's king can't escape the center, and the computer gives White a big advantage here. Remember the plan: d4, castle, take on e5, rook to d1."},"kxe5":{"title":"The king eats the pawn: checkmate!","intro":"You're in the position from the last chapter after 11.dxe5. Your e5 pawn sits right next to Black's king and nothing defends it. What happens if the king takes it?","moves":[{"c":"11...Kxe5?? The king grabbed the pawn and wandered even farther from home. Now chase him with checks!"},{"q":"The e-file is open and the king is standing on it. Which piece gives check?","c":"12.Re1+! The rook joins the attack with check."},{"c":"12...Kd6. The king tries to run."},{"q":"Give check with your queen. Look for the diagonal pointing straight at the king.","c":"13.Qg3+! The queen pushes the king back."},{"c":"13...Kd7. The king hid among his own pieces. But he blocked his own queen's view, so she isn't defending the d5 knight anymore!"},{"q":"Now only the c6 pawn defends the d5 knight. Capture it with your knight.","c":"14.Nxd5! You win the piece back. If the pawn takes your knight, a diagonal to the king opens up."},{"c":"14...cxd5?? Black captures and doesn't see what's coming."},{"q":"The king doesn't have a single free square. Find checkmate with your bishop!","c":"15.Bb5 mate! The queen on g3 guards d6 and c7, and the rook guards the whole e-file. Nobody can take the bishop, and nothing can block."}],"end":"The e5 pawn was poisoned! A king that wanders around the board grabbing pawns in the opening usually ends up in big trouble. Even taking with the knight didn't work: after 11...Nxe5 you play 12.Re1 and the knight is pinned."},"hungry":{"title":"The hungry knight: 8...Nb4","intro":"The second defense, and the toughest one according to the computer: the c6 knight jumps to b4. It defends the d5 knight and eyes the c2 pawn, threatening a check and fork on your king and rook. How do you spoil that fork?","moves":[{"c":"8...Nb4. The knight defends d5 and threatens 9...Nxc2+, a check and attack on the a1 rook."},{"q":"The knight wants to give a check and fork on c2. Move your king out of the way so it won't be check.","c":"9.O-O! Your king is tucked away, so taking on c2 isn't check anymore. If the knight takes right away (9...Nxc2), you take 10.Bxd5+ with check and get a huge advantage."},{"c":"9...c6. Black defends the d5 knight first."},{"q":"Same plan as always against a king in the center. Which pawn opens the game?","c":"10.d4! You attack the e5 pawn and open the path for your c1 bishop."},{"c":"10...Nxc2? The knight is hungry and goes after the a1 rook. While it's busy snacking, its king is left all alone."},{"q":"Don't save the rook! Take the pawn standing right in front of Black's king.","c":"11.dxe5! The d-file is open. The a1 rook was just bait."},{"c":"11...Nxa1. Black is up a rook and a knight. But their knight is stuck in the corner and their other pieces are still at home."},{"q":"Three pieces attack the d5 knight and three defend it. Bring a fourth attacker down the d-file.","c":"12.Rd1! All your pieces are attacking. Black has more pieces, just not where the fight is happening."},{"c":"12...Bc5. Black brings out a bishop, but it's too late."},{"q":"Start capturing on d5. Take with your knight first.","c":"13.Nxd5! You win a piece back. Now your queen, bishop, and rook are all aiming at d5."},{"c":"13...cxd5. Pawn takes knight."},{"q":"Take the d5 pawn with your bishop with check.","c":"14.Bxd5+. Check! The king can step back to d7 or grab the e5 pawn. Even if he steps back, you have a winning position."},{"c":"14...Kxe5?? The king grabbed the pawn and walked straight into checkmate."},{"q":"Checkmate in one move with the queen!","c":"15.Qf4 mate! Black is up a rook and a knight, and still lost."}],"end":"Count the pieces where the battle is happening! That knight in the a1 corner couldn't help anybody. If Black defended their king instead of 10...Nxc2, the game would go on and you'd have a strong attack for the knight."},"na5":{"title":"The right defense: 5...Na5","intro":"A strong opponent won't take on d5 with the knight. Instead, they attack your bishop and let you keep the pawn. Then there's no Fried Liver, and you need to play calmly and accurately.","moves":[{"c":"5...Na5! The best defense. The knight attacks the c4 bishop. Black gives up a pawn for fast development."},{"q":"Your bishop is attacked. Find a retreat that gives check at the same time.","c":"6.Bb5+! Moving back with check costs no time. Black has to deal with the check first."},{"c":"6...c6. The pawn blocks the check and attacks the bishop."},{"q":"Your bishop is attacked again. First, grab the pawn.","c":"7.dxc6. Pawn takes pawn."},{"c":"7...bxc6. Black takes back and attacks your bishop again. You kept your extra pawn."},{"q":"The bishop has to move back. Put it in front of your king where nothing can bother it.","c":"8.Be2. The bishop is safe."},{"c":"8...h6. The pawn chases away the g5 knight."},{"q":"Your knight is attacked. Bring it back to its favorite square.","c":"9.Nf3. The knight is back and attacks the e5 pawn."},{"c":"9...e4. The pawn chases the knight again. Black gains time — that's their reward for the pawn."},{"q":"The knight has only one good square, right in the center of the board.","c":"10.Ne5! The knight stands proud in the center. On the edge (h4) it would look silly, and going home (g1) would waste time."},{"c":"10...Bd6. The bishop develops and attacks the e5 knight."},{"q":"Support your e5 knight with a pawn.","c":"11.d4. The pawn defends the knight and opens the path for your c1 bishop."},{"c":"11...exd3. En passant capture! The e4 pawn took the pawn that jumped two squares past it. Now the e5 knight is unprotected again."},{"q":"Your e5 knight is attacked and undefended. Move it back while capturing a pawn.","c":"12.Nxd3. The knight is safe and you still have your extra pawn."}],"end":"You're up a pawn, and Black has faster development for it. The position is equal. Next you want to castle and develop your b1 knight and c1 bishop."},"nd4":{"title":"The bishop goes home: 5...Nd4","intro":"Black's third defense. The knight jumps to the center, and soon a pawn will attack your bishop. You'll learn a funny-looking move: your bishop goes all the way back to the square it started on.","moves":[{"c":"5...Nd4. The knight stands in the center and Black gets ready to play b5."},{"q":"Chase the knight out of the center with a pawn.","c":"6.c3! The pawn attacks the d4 knight."},{"c":"6...b5! Counterattack! The knight didn't move, and a pawn attacks your bishop."},{"q":"Your bishop is attacked. On b5, b3, or e2 the knight would take it. Where can it hide?","c":"7.Bf1! The bishop goes home! It looks weird, but nothing can attack it here and it still eyes the b5 pawn. The d4 knight is still under attack."},{"c":"7...Nxd5. Black wins the pawn back. At the same time, the knight cleared the way for the queen, which now attacks your g5 knight."},{"q":"The queen attacks your g5 knight. Move it to safety in the center.","c":"8.Ne4. The knight is safe and the c3 pawn still attacks the d4 knight. Taking the knight right away (8.cxd4) also works, though Black's queen would take your g5 knight and things get wilder."},{"c":"8...Ne6. The knight finally retreats."},{"q":"Now you can grab the b5 pawn. With check!","c":"9.Bxb5+. Extra pawn and check!"},{"c":"9...Bd7. The bishop steps in the way."},{"q":"Trade bishops.","c":"10.Bxd7+. When you're up a pawn, trading pieces helps you."},{"c":"10...Qxd7. The queen takes back."},{"q":"And now tuck your king into safety.","c":"11.O-O. You're up a pawn and your king is safe."}],"end":"Remember the move Bf1! It also works if Black plays 5...b5 right away: play 6.Bf1 again! Taking the pawn with 6.Bxb5 is worse because the queen takes d5 and attacks both your b5 bishop and g2 pawn. And if Black's queen comes to h4 after 8.Ne4, just move your knight back with 9.Ng3."},"h6":{"title":"Mistake 4...h6?","intro":"Many kids answer the g5 knight with h6 to chase it away. They forget to ask what the knight is aiming at.","moves":[{"c":"4...h6? The pawn attacks the knight. But only the king defends f7."},{"q":"The knight doesn't have to retreat. Where can it jump to attack two heavy pieces at once?","c":"5.Nxf7! A fork on the d8 queen and the h8 rook! The king can't take the knight because the c4 bishop protects it."},{"c":"5...Qe7. The queen ran away, leaving the rook behind."},{"q":"Collect your prize.","c":"6.Nxh8. You won a rook and a pawn!"}],"end":"Before chasing away an opponent's piece, check what it's aiming at. When your opponent doesn't defend f7, the g5 knight and c4 bishop punish them."},"nxe4":{"title":"Mistake 4...Nxe4?","intro":"Black might grab the e4 pawn and attack your knight at the same time. Taking the knight back looks most natural. But you can find something even better.","moves":[{"c":"4...Nxe4? The knight took the pawn and attacks your g5 knight. But only the king defends f7."},{"q":"Don't take the knight back! Only the king defends f7. Capture there with your bishop with check.","c":"5.Bxf7+! The king can't take the bishop because the g5 knight protects it. He has to move and loses the right to castle."},{"c":"5...Ke7. The only move."},{"q":"The king is stuck in the center. Open the game with a pawn that also lets your c1 bishop out.","c":"6.d4! You attack the e5 pawn, and your c1 bishop now protects the g5 knight."}],"end":"Black's king is stuck in the center and you have a big advantage. If you had taken the knight on move 5 (5.Nxe4), Black would play 5...d5 and the pawn would fork both your bishop and knight."},"traxler":{"title":"Traxler Counterattack 4...Bc5","intro":"Brave players ignore the g5 knight and aim their own bishop at your f2 square. It's called the Traxler Counterattack, named after Czech chess player Karel Traxler. It's full of tricks, so you'll take the safest path.","moves":[{"c":"4...Bc5!? Black doesn't defend f7 and aims at f2. If you take on f7 with your knight, the bishop gives check on f2 and things get super wild."},{"q":"Take the f7 pawn in a way that gives check. Then Black won't have time to take on f2.","c":"5.Bxf7+! An extra pawn, and Black's king can't castle anymore."},{"c":"5...Ke7. The king stands right next to your bishop. Only the g5 knight defends the bishop."},{"q":"If the h6 pawn chases your knight away, the king could take your bishop. Move your bishop back to the center.","c":"6.Bd5! The bishop is safe and eyes the c6 knight."},{"c":"6...Rf8. The rook lines up on the f-file behind the knight."},{"q":"The c5 bishop aims at f2 and the f8 rook lurks behind the knight. Tuck your king away and add a defender to f2.","c":"7.O-O! The rook defends f2 and your king is safe. Black's king is stuck in the center."}],"end":"You're up a pawn with a safe king, while Black's king is stuck in the center. The wild move 5.Nxf7 is even a tiny bit stronger according to the computer, but after 5...Bxf2+ you'd need to know lots of exact moves. We'll save that for later!"}}},"scandinavian":{"name":"Scandinavian Defense","intro":"An opening for Black against 1.e4. Your queen comes out super early, which you usually shouldn't do. Here, though, she has a cozy home and a clear plan. You don't need to memorize moves by heart: in each chapter you'll learn WHY each piece goes where it goes. In these chapters you play as Black. Based on the book Starting Out: The Scandinavian by Jovanka Houska.","chapters":{"main":{"title":"The queen goes on a trip","intro":"The Scandinavian Defense breaks a rule: the queen comes out right at the start. You'll find out why Black can get away with it and where the queen hides.","moves":[{"c":"1.e4. White takes the center."},{"q":"Attack the e4 pawn right away. With which pawn?","c":"1...d5! The Scandinavian Defense. On move one you ask White: are you taking or moving forward?"},{"c":"2.exd5. White takes."},{"q":"Take the pawn back. Only one piece can reach it. Which one?","c":"2...Qxd5. The queen stands in the center and the c8 bishop has a clear path out. There's a small price: White will attack the queen and gain a little time."},{"c":"3.Nc3. The knight develops and attacks the queen. Notice, though, that it stands in front of the c2 pawn. That means White can't put pawns on c4 and d4 side by side. Just what you wanted!"},{"q":"The queen has to run. Find a square on the edge where nothing attacks her and she peeks at the c3 knight.","c":"3...Qa5. Here the queen is peaceful and eyes the c3 knight. Golden rule: from now on, the queen only moves if she really has to. Every extra queen move is a gift to White."},{"c":"4.d4. White has one pawn in the center. You'll build a strong wall against it."},{"q":"Bring out your knight to its best square.","c":"4...Nf6. The knight guards the d5 and e4 squares. In the Scandinavian, those are your squares."},{"c":"5.Nf3."},{"q":"The queen needs a hallway back home. Which pawn opens it and also guards b5 and d5?","c":"5...c6! A little home for the queen. Whenever she needs to, she can slip back along the hallway from a5 to d8. And White's knight can't jump to b5 or d5."},{"c":"6.Bc4."},{"q":"Now the c8 bishop. It has to come out before the e6 pawn closes the door.","c":"6...Bf5! This is called the Scandinavian bishop, and it's your best piece. If you played e6 first, it would be trapped at home."},{"c":"7.Bd2. Watch out, a trap! The bishop peeks through the knight at your queen. If the c3 knight jumps away, the bishop will attack your queen. Without the c6 pawn, 8.Nd5 would win the queen. Luckily you have your hallway!"},{"q":"The bishop is out, so you can close the door. Put a pawn next to c6.","c":"7...e6. Your pawn wall on c6 and e6 is ready, and the f8 bishop has a clear path out."}],"end":"Your setup: queen on a5, knight on f6, pawns on c6 and e6, bishop on f5. The queen only moves when she must. In the next chapters, you'll see how White might try to surprise you."},"d5":{"title":"Explosion in the center: watch out for d4-d5","intro":"You moved your queen twice while White developed pieces, so White has more pieces in play. Whoever has more pieces out wants to open the center. White will do it with d4-d5 if you let them. This is the biggest danger in the Scandinavian.","moves":[{"c":"8.Qe2. The queen guards the c4 bishop and gets ready for the d4-d5 explosion. After that, the c3 knight would jump away and the d2 bishop would attack your queen."},{"q":"Stop the explosion! Put a piece as a shield between the d2 bishop and your queen.","c":"8...Bb4! The bishop stands like a shield in front of your queen. It also attacks the c3 knight that guards d5. The explosion is stopped!"},{"c":"9.O-O-O. White castled queenside."},{"q":"Bring out your last knight. Square c6 is taken, so where does it go?","c":"9...Nbd7. The knight guards e5 and supports its buddy on f6."},{"c":"10.a3. The pawn asks the bishop: what now?"},{"q":"Your bishop is attacked. Don't retreat! Trade it for the knight that guards d5.","c":"10...Bxc3. You traded your bishop for the knight. White has two bishops, but no white knight guards d5 or e4 anymore. Those squares are yours."},{"c":"11.Bxc3. The bishop takes back and attacks your queen."},{"q":"Now the queen really has to move. The hallway is ready. Pick the square where she also guards e5.","c":"11...Qc7. The queen only moved when she had to. From c7, she teams up with the knight to guard e5."}],"end":"Next you'll castle and plant a knight on d5. What if you had played an ordinary 8...Nbd7 against 8.Qe2? White would play 9.d5! The center explodes, the c3 knight jumps to d5, and the d2 bishop attacks your queen. Even Grandmaster Larsen got into huge trouble like that against Spassky. Grabbing the pawn with 8...Bxc2 is even worse — White plays 9.d5 anyway! Being greedy doesn't pay off in the Scandinavian."},"shirov":{"title":"The knight leap 8.Nd5","intro":"This is White's sharpest try, made famous by Grandmaster Shirov. The knight jumps to d5 even though two pawns and a knight are attacking it. Why can White get away with that?","moves":[{"c":"8.Nd5! The knight jumped away and the d2 bishop attacks your queen. You can't take the knight: after 8...cxd5, the bishop would take your queen!"},{"q":"Your queen is under attack. Now the little home from Chapter 1 pays off! Where does the hallway lead?","c":"8...Qd8. The only good move. The queen is safe at home and the d5 knight is attacked three times."},{"c":"9.Nxf6+. Knight takes knight with check."},{"q":"Take back with a pawn. This opens the g-file for your rook.","c":"9...gxf6. The pawns look funny, but they have a job: the f6 pawn guards e5 so White's knight can't jump there. Taking with the queen works too, but the queen would be moving for the fourth time."},{"c":"10.Bb3. The bishop steps back to safety."},{"q":"Bring out your knight. Square c6 is taken.","c":"10...Nd7. This knight guards e5 too."},{"c":"11.Qe2."},{"q":"Your king wants to castle queenside. Clear the way with your queen.","c":"11...Qc7. The king will go to the queenside because the g-pawn is missing on the kingside."},{"c":"12.O-O-O. White's king goes to the queenside."},{"q":"Tuck your king into safety. Which side?","c":"12...O-O-O. Your king is safe and your rook faces the d4 pawn."},{"c":"13.Nh4. White is hunting your Scandinavian bishop."},{"q":"Your bishop is attacked. It's your best piece — save it!","c":"13...Bg6! The only good move. If you left the bishop there, the knight would take it and wreck your pawns. If the knight takes your bishop on g6 now, you take back with the h-pawn and open a file for your rook."}],"end":"The 8.Nd5 jump looked scary, but thanks to your hallway nothing bad happened. Your plan: the d7 knight goes via b6 to d5, and later you strike White's center with c6-c5."},"storm":{"title":"Knight on e5 and the pawn storm","intro":"Some White players don't wait around. They jump a knight to the center and rush their g and h pawns at your bishop. It looks scary! But anyone who pushes pawns away from their own king leaves holes behind.","moves":[{"c":"7.Ne5. The knight stands in the center and teams up with the c4 bishop to aim at f7."},{"q":"Block the c4 bishop's path to f7.","c":"7...e6. The wall is up and f7 is safe."},{"c":"8.g4! The pawn attacks your bishop."},{"q":"Step back with your bishop so it stays on its diagonal.","c":"8...Bg6. The bishop stepped back. That g4 pawn can never go backward to defend its king."},{"c":"9.h4. Another pawn! White threatens h5, leaving the bishop nowhere to hide."},{"q":"Don't panic. First, challenge that strong e5 knight.","c":"9...Nbd7! Golden rule: whenever White's knight lands on e5, send your b8 knight right after it."},{"c":"10.Nxd7."},{"q":"Take back with the f6 knight. That frees the e4 square for your bishop.","c":"10...Nxd7. The f6 knight moved away and the g6 bishop has an open diagonal."},{"c":"11.h5. The bishop is attacked. It looks trapped!"},{"q":"The bishop has just one escape square — and from there it attacks something right away!","c":"11...Be4! The bishop escaped and attacks the h1 rook."},{"c":"12.Rh3. The rook stepped aside."},{"q":"The rook ran away, so chase it!","c":"12...Bg2! The bishop attacks the rook again. White's pawns ran too far forward and nobody can chase the bishop away."},{"c":"13.Re3."},{"q":"Attack the c4 bishop with your knight and get ready to jump to d5.","c":"13...Nb6. The knight attacks the bishop and gets ready for the d5 square."}],"end":"The storm blew over and your bishop survived! White's king has nowhere safe to live because the pawns in front of him ran away. Remember: answer an e5 knight with Nbd7, and don't castle kingside while the g and h pawns are charging at you."},"bc4":{"title":"Bishop to c4 without Nf3: queen to b6","intro":"Watch out for a sneaky White player! Sometimes they skip Nf3 and put their bishop straight on c4. If you play like usual (c6, Bf5, e6), White plays Qe2 and d4-d5 and blows up your center. The book has a different plan for this.","moves":[{"c":"5.Bc4. The g1 knight stayed home. When your opponent skips a move, they have a reason."},{"q":"Nothing stands between g4 and White's queen on d1. Which piece attacks the queen?","c":"5...Bg4! The bishop attacks the queen. Both the book and Stockfish say this is the best move."},{"c":"6.f3. The pawn blocks the bishop. But it stole the knight's best square, f3, and opened a path toward White's king."},{"q":"Your bishop is attacked. Step back to the diagonal where it stays active.","c":"6...Bf5. The bishop sits on its favorite diagonal. Stockfish actually likes retreating to d7 slightly better so the g and h pawns can't chase it — the app accepts that move too."},{"c":"7.Bd2. Watch out! The bishop peeks through the knight at your queen. You don't have a c6 pawn, so your queen has no hallway. White threatens 8.Nd5 to trap your queen!"},{"q":"Move your queen to safety before the knight jumps. Find a square where she attacks the d4 pawn.","c":"7...Qb6! The queen is out of danger and attacks the d4 and b2 pawns. If you played 7...e6?, 8.Nd5! would trap your queen."},{"c":"8.g4. The pawn chases the bishop."},{"q":"Step back with the bishop so it stays on its diagonal.","c":"8...Bg6. This is how most games in the book go. Stockfish would rather tuck the bishop back on d7 where the pawns can't catch it — the app accepts that move too."},{"c":"9.h4. White wants to play h5 and trap the bishop."},{"q":"Make an escape square for your bishop. With which pawn?","c":"9...h6! When h5 comes, the bishop can slip back to h7."},{"c":"10.Nge2. The knight finally comes out, through e2 instead of f3."},{"q":"Your queen is safe, so now you can close the door.","c":"10...e6. Now the f8 bishop has a clear path out."},{"c":"11.Nf4. The knight attacks your g6 bishop and eyes the e6 pawn."},{"q":"Don't retreat the bishop. Attack the d4 pawn with another piece instead!","c":"11...Nc6! Both the book and Stockfish prefer this over retreating the bishop. If the knight takes your bishop on g6, you take back with the f-pawn and your rook gets an open file."}],"end":"Remember: when White skips Nf3 and puts a bishop on d2, your queen goes to b6. The usual c6 and e6 routine isn't enough here. After 5...c6?! 6.Bd2 Bf5 7.Qe2 e6?, 8.d5! blows open the center just as White wanted."},"quiet":{"title":"Quiet White: pin the knight","intro":"Many opponents don't play d4 right away. They develop their pieces and castle quickly. When they do, your bishop can go one square farther and pin the f3 knight.","moves":[{"c":"4.Nf3."},{"q":"Start as usual: knight out.","c":"4...Nf6."},{"c":"5.Bc4."},{"q":"Here too, build the queen's hallway first.","c":"5...c6. If White attacks the queen with b4, she has somewhere to retreat."},{"c":"6.O-O?! White castled in a hurry. Their king already lives on the kingside, and that's a big clue for you."},{"q":"White won't want to push the g and h pawns in front of their own king. Pin the f3 knight with your bishop.","c":"6...Bg4! The f3 knight can't move because the queen stands behind it. Before White castles, the bishop belongs on f5 so the g and h pawns don't chase it."},{"c":"7.h3. The pawn questions the bishop."},{"q":"Keep the pin! Step back one square with the bishop.","c":"7...Bh5. The pin stays on. If White plays g4, they weaken the pawns guarding their own king."},{"c":"8.Re1."},{"q":"Bring out your second knight.","c":"8...Nbd7."},{"c":"9.d4."},{"q":"Your bishop is out, so close the door.","c":"9...e6. The c6 and e6 wall is up."},{"c":"10.Bd2. You know this trick: the bishop peeks through the knight at your queen. The queen on a5 isn't safe anymore."},{"q":"Now the queen has to move. Pick the square where she guards e5.","c":"10...Qc7. The queen moved only when she had to."}],"end":"Next you'll bring your bishop to d6 or e7 and castle kingside. Then you'll strike the center with c6-c5."},"short":{"title":"Short System: hole on d4","intro":"English Grandmaster Nigel Short used to play this system. White plays a quiet d3 instead of d4. That leaves the d4 square with no pawn guarding it, making a cozy home for your knight.","moves":[{"c":"4.Bc4. White develops the bishop first."},{"q":"Knight out.","c":"4...Nf6."},{"c":"5.d3. The pawn moves just one square. The d4 square is left without a pawn — remember it!"},{"q":"A trick you know from Chapter 5: nothing stands between g4 and White's queen. Attack her!","c":"5...Bg4! The book calls this the best move. White has to do something about the queen."},{"c":"6.f3. The pawn blocked the path and weakened the light squares around the king."},{"q":"Step back with your bishop. This time go home to d7, where the g and h pawns can't chase it.","c":"6...Bd7. The bishop is safe, and White is stuck with a weak f3 pawn."},{"c":"7.Bd2. You know this: the bishop peeks through the knight at your queen."},{"q":"Queen to safety! Which square do you remember from Chapter 5?","c":"7...Qb6. The queen steps off the d2 bishop's diagonal and eyes the b2 pawn."},{"c":"8.Qe2."},{"q":"Bring your knight out toward the hole on d4.","c":"8...Nc6. The knight is aiming for d4."},{"c":"9.O-O-O. White's king goes to the queenside."},{"q":"Jump your knight into the hole and attack White's queen at the same time.","c":"9...Nd4! The knight stands tall in the center and attacks the e2 queen. Only c3 could chase it away, and that would open lines toward White's king."},{"c":"10.Qe5. The queen stepped aside and attacks the c7 pawn."},{"q":"Block the c4 bishop's path to f7 and open the way for your f8 bishop.","c":"10...e6. Stockfish rates the position as equal. French Grandmaster Prie played this exact line against Mamedyarov."}],"end":"Against the Short System: bishop to g4 forces f3, then goes back to d7. When Bd2 comes, queen goes to b6. Your knight takes over the hole on d4."},"mieses":{"title":"The b4 gift: Mieses Gambit","intro":"White offers you a free pawn to open the b-file and chase your queen. Whenever someone offers a gift, ask: can I take it safely? Here, yes!","moves":[{"c":"4.b4!? The pawn attacks your queen and nobody defends it."},{"q":"Is that pawn really free? Check if anything defends it.","c":"4...Qxb4. Free pawn! You're up a pawn."},{"c":"5.Rb1. The rook attacks your queen and eyes the b7 pawn."},{"q":"The queen has to move. Bring her back toward the center, out of the rook's reach.","c":"5...Qd6. The queen stands in the center and guards the c7 pawn."},{"c":"6.d4."},{"q":"Knight out.","c":"6...Nf6."},{"c":"7.Nf3."},{"q":"White's knight would love to jump to b5 and attack your queen. Take that square away with a pawn.","c":"7...a6! A tiny move, a big help. The knight can't go to b5, and your queen has peace."},{"c":"8.Bc4."},{"q":"Block the c4 bishop's path to f7.","c":"8...e6."},{"c":"9.O-O."},{"q":"Bring out your bishop and get ready to castle.","c":"9...Be7."},{"c":"10.Re1."},{"q":"King to safety.","c":"10...O-O. Your king is safe and you still have your extra pawn."}],"end":"White got an open b-file for the pawn, and that's not enough. You took the gift, tucked your queen away, and castled fast. That's how you answer a gambit!"},"nf3":{"title":"White skips Nc3: smash the big center","intro":"A sneaky White player doesn't attack your queen with the knight. They keep their c-pawn free to build a big c4 and d4 center. You'll smash it with fast development and queenside castling.","moves":[{"c":"3.Nf3. White plans to attack the queen later with c4."},{"q":"Nobody is attacking your queen, so you have a free move. Bring out your bishop and pin the knight.","c":"3...Bg4. The f3 knight is pinned and can't help guard the d4 square."},{"c":"4.Be2. White breaks the pin."},{"q":"This time you don't need the c6 hallway because nobody is chasing your queen. Put your knight on c6 aiming at d4.","c":"4...Nc6. The knight aims straight at d4."},{"c":"5.d4."},{"q":"How can you add another attacker to the d4 pawn and tuck your king away at the same time?","c":"5...O-O-O! Your rook lines up right behind your queen. Your queen, rook, and knight all attack the d4 pawn."},{"c":"6.c4. White builds the big center and attacks your queen."},{"q":"The queen has to move. Find a square where she protects the g4 bishop.","c":"6...Qf5. The queen guards the bishop, and now the d8 rook stares straight at the d4 pawn."},{"c":"7.Be3. The bishop defends the d4 pawn. Is it enough?"},{"q":"The f3 knight also defends d4. Remove that defender!","c":"7...Bxf3! One defender gone."},{"c":"8.Bxf3."},{"q":"Your knight and rook attack d4. Capture!","c":"8...Nxd4! Both the bishop and queen defend it, so it looks even. But you have a check waiting!"},{"c":"9.Bxd4."},{"q":"Don't take back right away. Give check with your queen first.","c":"9...Qe6+! White's king is in check and the d4 bishop is still attacked by your rook."},{"c":"10.Be2. White blocks with the bishop."},{"q":"Attack two things at once with your queen: the d4 bishop and the g2 pawn.","c":"10...Qe4! Double attack! White can't save both."},{"c":"11.O-O. White saves the g2 pawn and leaves the bishop."},{"q":"The bishop is undefended. Take it with your queen.","c":"11...Qxd4. Pieces are even, and you're up a pawn!"},{"c":"12.Qa4. White avoids trading queens and eyes the a7 pawn."},{"q":"Check if the a7 pawn is really in danger. If something guards it, go ahead and open the way for your f8 bishop.","c":"12...e6. Your queen guards a7 diagonally from d4. The f8 bishop can come out, and you kept your extra pawn."}],"end":"The big center crumbled! Play the same way if White starts with 3.d4: play 3...Nc6, then Bg4 and castle queenside. Every piece aims at the d4 pawn."},"nc3":{"title":"2.Nc3: back to familiar territory","intro":"Some opponents try to avoid the Scandinavian by not taking the d5 pawn. You'll show them there's no escape.","moves":[{"c":"1.e4."},{"q":"Attack the e4 pawn.","c":"1...d5."},{"c":"2.Nc3. White doesn't take. They defend e4 with a knight."},{"q":"White didn't take, so you take.","c":"2...dxe4."},{"c":"3.Nxe4."},{"q":"You want to reach a position you already know. Put your queen in the center and attack the knight.","c":"3...Qd5! The queen attacks the e4 knight."},{"c":"4.Nc3. The knight steps back and attacks your queen. Recognize this position?"},{"q":"Where does the queen belong?","c":"4...Qa5. The exact same position as in Chapter 1! Everything you learned still applies."},{"c":"5.d4."},{"q":"Remember the order? Knight first.","c":"5...Nf6."},{"c":"6.Nf3."},{"q":"Then the hallway for the queen.","c":"6...c6."},{"c":"7.Bc4."},{"q":"And the Scandinavian bishop comes out before you close the door.","c":"7...Bf5."}],"end":"Your opponent tried to dodge the Scandinavian, and you steered them right back into it! Knight, hallway, bishop, and only then e6."},"e5":{"title":"2.e5: strike right away with c5","intro":"White can also push the pawn forward. The book isn't a fan of this move: you get for free what you usually have to fight for. The key is to strike before White gets comfy.","moves":[{"c":"1.e4."},{"q":"Attack the e4 pawn.","c":"1...d5."},{"c":"2.e5?! The pawn ran forward. The center is closed and your d5 pawn stayed put. White doesn't have a d4 pawn yet to support the e5 pawn."},{"q":"The d4 square is still empty. Claim it before White does: attack it with a pawn.","c":"2...c5! The book recommends this move. When White plays d4, you'll attack it right away. Best of all, your c8 bishop's door is still open."},{"c":"3.c3. White prepares d4."},{"q":"Bring out your knight so it eyes both d4 and the e5 pawn.","c":"3...Nc6. The knight watches d4 and attacks the e5 pawn."},{"c":"4.d4. White builds a pawn chain on c3, d4, and e5."},{"q":"The door is still open. Which piece should come out before you play e6?","c":"4...Bf5! The bishop is outside the pawn chain. This time your queen didn't have to move once — you didn't lose any time."},{"c":"5.Nf3."},{"q":"Now close the door and support your d5 pawn.","c":"5...e6. Your f8 bishop has a clear path, and both your c5 pawn and c6 knight attack the d4 pawn."}],"end":"Against 2.e5: first strike d4 with c5, then knight to c6, bishop out to f5, and finally e6. Later your queen goes to b6 to put even more pressure on d4."},"nf6":{"title":"Another path: 2...Nf6","intro":"You don't have to take the d5 pawn with your queen. You can send a knight after it instead. White gets a big center, and you attack it with your pieces. It's a different style — try it out!","moves":[{"c":"1.e4."},{"q":"Attack the e4 pawn.","c":"1...d5."},{"c":"2.exd5."},{"q":"This time leave the queen at home. Send a knight after the pawn.","c":"2...Nf6. The knight develops and attacks the d5 pawn."},{"c":"3.d4."},{"q":"Take the pawn back.","c":"3...Nxd5. Material is equal."},{"c":"4.c4. The pawn chases the knight away. White got the big c4 and d4 center that you stopped them from building in Chapter 1."},{"q":"Step back with your knight to a square where it attacks the c4 pawn.","c":"4...Nb6."},{"c":"5.Nf3."},{"q":"Your f8 bishop wants to aim at the d4 pawn from the long diagonal. Make room for it.","c":"5...g6. The bishop will go to g7."},{"c":"6.Nc3."},{"q":"Bishop to the long diagonal.","c":"6...Bg7. The bishop aims all the way across the board at the d4 pawn."},{"c":"7.h3. White stops your bishop from coming to g4."},{"q":"King to safety.","c":"7...O-O."},{"c":"8.Be3. The bishop defends the d4 pawn."},{"q":"Add another attacker to the d4 pawn.","c":"8...Nc6. Both the g7 bishop and the c6 knight aim at d4."},{"c":"9.Qd2."},{"q":"Your pieces are ready. Strike the center with a pawn!","c":"9...e5! You've been getting ready for this move the whole time. The big center has to budge."},{"c":"10.d5. The pawn attacks your knight."},{"q":"Step back with the knight so it stays close to the center.","c":"10...Ne7. From here the knight can head to f5."}],"end":"In this line White gets a big center, and you surround it with pieces before striking with e5. It's a sharper game. When you're starting out, the path with the queen on a5 is steadier."}}},"italian":{"name":"Italian Game – Basics","intro":"The Italian Game the way the world's best players play it today: slowly, with a plan, and with patience. Most chapters are real grandmaster games from the book The Modernized Italian Game for White. You are not memorizing moves—you are discovering WHY each piece goes where it goes.","chapters":{"rules":{"title":"Three Rules and the Quiet Italian","intro":"The Italian Game is one of the oldest openings. Today even world champions play it, just differently than long ago: slowly and wisely. It is called Giuoco Pianissimo, which means \"the quietest game\" in Italian. First you put all your pieces on good squares, and only then do you attack.","moves":[{"q":"Take the center with a pawn. Which pawn opens the door for both your bishop and your queen?","c":"1.e4. The pawn stands in the center, and both the f1 bishop and the queen have an open door."},{"c":"1…e5. Black does the same."},{"q":"Bring out a knight so it attacks something right away.","c":"2.Nf3. The knight develops and attacks the e5 pawn. Developing with an attack is the best kind of development."},{"c":"2…Nc6. Black defends the pawn."},{"q":"Where should you put your bishop to aim at Black's weakest square?","c":"3.Bc4. This is the Italian Game. Only the king defends f7, so your bishop aims right at it."},{"c":"3…Bc5. Black's bishop aims at your f2 square."},{"q":"A small pawn move that guards the b4 and d4 squares. Can you find it?","c":"4.c3. One move, three jobs: the pawn takes away b4 and d4 from Black's pieces, prepares d4 for later, and opens an escape square on c2 for your bishop."},{"c":"4…Nf6. Black attacks your e4 pawn."},{"q":"Your e4 pawn is attacked. Defend it calmly with a pawn.","c":"5.d3. This is the quiet Italian. The pawns on c3, d3, and e4 form a strong chain. You save d4 for later, when all your pieces are ready."},{"c":"5…d6. Black also builds a solid center."},{"q":"Third rule: where does the king belong?","c":"6.O-O. The king is safe and the rook enters the game."}],"end":"Center, development, castling: all three rules are done. You didn't sacrifice anything and nothing threatens you. In the next chapters you'll see what great plans grow out of this cozy house."},"home":{"title":"A Little Home for the Bishop","intro":"Your c4 bishop is your most important piece. Your opponent will try to trade it off or chase it away. So you build it a little home where nobody can catch it.","moves":[{"c":"6…a6. Black builds a home for their bishop on a7. They are also getting ready to play b5 and attack your bishop."},{"q":"Stop the b5 pawn and open the a2 square for your bishop at the same time.","c":"7.a4! Your pawn guards the b5 square. And a2 is now free: that's the little home for your bishop."},{"c":"7…Ba7. Black's bishop hides early. If it stayed on c5, your pawns could attack it with b4 or d4 and you would gain time."},{"q":"Put your rook behind the e4 pawn. This clears the f1 square.","c":"8.Re1. The rook defends the e4 pawn and leaves f1 free for a knight. You'll see why in the next chapter."},{"c":"8…O-O. Black castles."},{"q":"Make a breathing window for your king and take the g4 square away from Black's bishop.","c":"9.h3. Black's bishop can no longer jump to g4 and pin your knight. Plus, your king gets a little window on h2."},{"c":"9…Na5. The knight attacks your bishop! Black wants to trade it off."},{"q":"Your bishop is attacked. Where is its little home?","c":"10.Ba2! The bishop is safe at home. The knight can't reach it there, and the bishop still aims across the whole board at f7. Meanwhile, Black's knight is stuck on the edge with few squares."},{"c":"10…c5. Black makes room so the knight can come back through c6."},{"q":"Bring out your last knight. A pawn stands on c3, so where will it go?","c":"11.Nbd2. All your pieces are ready. Your bishop survived the hunt and your opponent lost time."}],"end":"Don't let your c4 bishop be traded for a knight. The moves a4 and Ba2 keep it safe. Also notice h3: a tiny window that stops your opponent's pin before it happens."},"slow":{"title":"The Traveling Knight: b1–d2–f1–g3","intro":"Game Gipslis – Ruderfer, Moscow 1979. The b1 knight would love to jump to c3, but a pawn is sitting there. So it packs its backpack and goes on a long trip around the board all the way to the enemy king. Watch out: you only have time for this trip when the center is closed and solid.","moves":[{"q":"The trip begins! The c3 square is taken. Where does the knight jump?","c":"6.Nbd2. First stop. For now, the knight guards the e4 pawn and its friend on f3."},{"c":"6…a6. Black prepares b5 to chase your bishop."},{"q":"Your bishop doesn't wait for the b5 pawn to attack it. Where does it step back ahead of time?","c":"7.Bb3. The bishop hides before the attacker arrives, while still aiming at f7."},{"c":"7…O-O. Black's king tucks into the corner."},{"q":"And your king?","c":"8.O-O. Your king is safe too."},{"c":"8…Ba7. Black's bishop also finds a home, far away from pawns that might chase it."},{"q":"Your knight needs its next stop on f1, but a rook is standing there. Clear the square!","c":"9.Re1. The rook frees up f1 and guards the e4 pawn at the same time. One move, two good things."},{"c":"9…Ne7. Black's knight travels too: from c6 through e7 to g6."},{"q":"Your opponent's c8 bishop would love to jump to g4 and pin your knight. Shut the door on it!","c":"10.h3. The g4 square is locked. And your king gets a breathing window on h2."},{"c":"10…Ng6. Black's knight reaches its goal."},{"q":"Second stop for the traveling knight.","c":"11.Nf1. The knight lands on the square the rook cleared for it."},{"c":"11…h6. Black doesn't want you jumping to g5."},{"q":"Last stop: a square from which the knight can reach both f5 and h5.","c":"12.Ng3! The knight has arrived. From here it can jump straight to f5 right in front of Black's king."}],"end":"The knight made four hops: b1, d2, f1, g3. On an empty board it could do it in two, but your center pawns keep your opponent in check, so you can afford the slower trip. In a later chapter you'll see what this knight did next in the game."},"early4":{"title":"Experiment: What If I Play d4 Right Away?","intro":"In the quiet Italian you play 5.d3 and save d4 for later. Why? Let's run an experiment: play d4 right away and watch what happens to your center. This is how the Italian Game used to be played for over a hundred years.","moves":[{"q":"The experiment begins. This time, strike the center with your pawn right away.","c":"5.d4. The pawn attacks both the c5 bishop and the e5 pawn. Looks awesome."},{"c":"5…exd4. Black takes."},{"q":"Take back so you have two pawns side by side in the center.","c":"6.cxd4. A gorgeous center, and the c5 bishop is attacked. If it retreats to b6, your pawns would march with d5 and e5 and Black's knights would have to run all over the board."},{"c":"6…Bb4+! But Black doesn't retreat. Black gives check. Your king hasn't castled yet, so you have to deal with the check instead of attacking."},{"q":"Block the check with a piece that develops at the same time.","c":"7.Bd2. The calmest reply."},{"c":"7…Bxd2+. Black trades bishops."},{"q":"Take back with the b1 knight so it develops too.","c":"8.Nbxd2. The knight enters the game and protects the e4 pawn."},{"c":"8…d5! This move is why the experiment didn't work out. The pawn attacks both your c4 bishop and your e4 pawn at once."},{"q":"One pawn attacked two of your things. Capture it.","c":"9.exd5. You have nothing better. Out of your big center, only the d4 pawn is left."},{"c":"9…Nxd5. The knight sits in the middle and none of your pawns can chase it away."},{"q":"Attack the d5 knight with your queen and bishop together.","c":"10.Qb3. Queen and bishop press on d5. You might recognize this pair from the Evans Gambit."},{"c":"10…Nce7. The second knight guards the first one. Black defended everything."},{"q":"King to safety.","c":"11.O-O."},{"c":"11…O-O."},{"q":"Put a rook on the open e-file.","c":"12.Rfe1. Look at the center. Out of two pawns, only one is left and it stands alone. It is called an isolated pawn because another pawn will never guard it again. The game is equal."}],"end":"The experiment showed that after 5.d4, Black breaks up your center with a check on b4 and …d5. It isn't bad for you, but you have no advantage. That is why today's masters play 5.d3: first castle and develop, and only play d4 when a check on b4 won't bother you."},"d4":{"title":"Prepare First, Then Strike","intro":"We continue the game Gipslis – Ruderfer. All your pieces are on good squares. Now it is time to strike in the center and then make a jump that breaks open Black's king fortress.","moves":[{"c":"12…c6. Black is also getting ready to push a pawn to d5."},{"q":"Everything is ready. Strike the center with your pawn!","c":"13.d4! Now that all your pieces are developed, d4 is a strong move. The c3 pawn supports it and the center belongs to White."},{"c":"13…Qc7. Black's queen defends the e5 pawn."},{"q":"Bring out your last minor piece. Place it facing Black's a7 bishop.","c":"14.Be3. The bishop stands opposite the a7 bishop and guards the d4 pawn."},{"c":"14…b5. Black wants to gain space on the queenside."},{"q":"The queen joins the bishop. Which square near Black's king do they aim at together?","c":"15.Qd2. Queen and bishop line up on the same diagonal and both aim at the h6 pawn in front of Black's king."},{"c":"15…Kh7. The king steps up to defend the h6 pawn."},{"q":"Bring the last piece that is still sleeping into the center.","c":"16.Rad1. Now all your pieces are playing. Time to attack!"},{"c":"16…Bb7. Black finishes developing."},{"q":"The traveling knight is at its goal. Jump right in front of Black's king!","c":"17.Nf5! The knight stands right in front of Black's king and attacks the g7 and h6 pawns."},{"c":"17…Nxe4. Black grabbed a pawn and attacked your queen! They think they surprised you."},{"q":"Your queen is attacked. Step back so she still aims at h6.","c":"18.Qc1! The queen steps away, yet from c1 through the e3 bishop she still aims at h6. Now Black has to do something about the f5 knight."},{"c":"18…Bc8. The bishop wants to take the f5 knight."},{"q":"Before the bishop takes your knight, let the knight give the king a big scare. Which pawn should it take?","c":"19.Nxg7! The knight crashes into Black's king's house. If the king captures it, Bxh6+ comes next and the c1 queen joins the attack. Gipslis won this game."}],"end":"Remember the order: first put every piece on a good square, then play d4 in the center, and only then attack the king. Anyone who rushes an attack without getting ready attacks all alone with one piece."},"queenside":{"title":"Queenside Pawns: b4, a4, a5","intro":"Game Dolmatov – Kholmov, Moscow 1982. You can attack on the other side of the board too! Your b and a pawns can march forward and take away Black's space. Black cannot do the same because their c6 knight blocks their pawns.","moves":[{"q":"The c5 bishop would like to hide on a7. Attack it with a pawn before Black plays a6.","c":"6.b4. The bishop has to move back and Black didn't have time to prepare a7."},{"c":"6…Bb6."},{"q":"Send up the second pawn. You threaten a5 to trap the bishop.","c":"7.a4! If Black does nothing, after a5 the bishop has nowhere to go."},{"c":"7…a6. Black makes the a7 square ready for the bishop."},{"q":"King to safety.","c":"8.O-O."},{"c":"8…h6."},{"q":"The knight can't go to c3 because a pawn is there. Find a path for it to c4.","c":"9.Na3. The knight travels through a3 to c4. From there it will aim at b6, where Black has a hole."},{"c":"9…O-O."},{"q":"Clear the c1 square so your rooks can connect.","c":"10.Bd2. The book's authors actually prefer Nc4 right away here, though this works too."},{"c":"10…Ne7. Black's knight goes through e7 to g6."},{"q":"Black is getting ready for c6 and d5. Tuck your bishop away where a pawn can't hit it.","c":"11.Ba2. The bishop is safe and still points at f7."},{"c":"11…c6."},{"q":"Guard the e4 pawn with your queen.","c":"12.Qe2."},{"c":"12…Ng6."},{"q":"Attack the b6 bishop!","c":"13.a5! The bishop must retreat, and your a5 and b4 pawns have taken over Black's queenside. A hole opened up on b6."},{"c":"13…Bc7."},{"q":"Now send the knight to its target square.","c":"14.Nc4. The knight eyes the holes on b6 and d6. Black preferred to trade it off right away for a bishop, but your pawns kept Black's queenside locked up for a long time."}],"end":"The c3, b4, and a5 pawns took away Black's room and left a hole on b6. Later in the game White's knight really did hop in there, and the pawn break b4–b5 won the game. When you attack with pawns on the queenside, your own king stays safe on the other side."},"attack":{"title":"King Attack: Call Your Friends","intro":"Game Gavrikov – Van der Sterren, Tallinn 1987. One attacker cannot beat a king. You have to bring more attackers than the king has guards. White starts with an unusual move: the knight steps back to the edge!","moves":[{"q":"Your queen wants to go to f3, but a knight is in the way. Move it to the edge so it can jump to g4.","c":"12.N3h2!? Looks funny, but it has two smart reasons. Square f3 opens up for the queen, and the knight will jump to g4, closer to Black's king."},{"c":"12…Bxb3. Black trades bishops."},{"q":"Take back with a pawn. Which pawn moves closer to the center?","c":"13.axb3. The a-pawn steps toward the center and the a1 rook gets an open file."},{"c":"13…a5."},{"q":"The second knight heads to its favorite stopping square.","c":"14.Ng3. The knight aims at f5."},{"c":"14…d5. Black strikes in the center."},{"q":"Now f3 is empty. Bring out the queen!","c":"15.Qf3. The queen guards the e4 pawn and stands close to Black's king."},{"c":"15…dxe4. Black captures the pawn."},{"q":"Take back with a pawn.","c":"16.dxe4. The center is solid again."},{"c":"16…Re6. The rook comes over to help defend the king."},{"q":"Square f5 is free and nobody guards it. Jump in!","c":"17.Nf5! The knight stands right in front of Black's king. The first attacker is in place."},{"c":"17…Qf8. Black's queen comes to guard the g7 pawn."},{"q":"Bring the queen next to the knight. Together they aim at one pawn in front of the king. Which one?","c":"18.Qg3. Queen and knight attack g7. Black's king has to be careful."},{"c":"18…Kh8. The king runs into the corner."},{"q":"Call in the third friend: the knight from h2.","c":"19.Ng4! It attacks the f6 knight—the king's main bodyguard—and the h6 pawn too."},{"c":"19…Nh7. Black's knight pulls back to defend."}],"end":"Count the attackers near Black's king: knight on f5, knight on g4, and queen on g3. And the c1 bishop is waiting for its chance to jump to h6. You'll see how the attack ended in the next chapter."},"gavfin":{"title":"King Attack: The Grand Finale","intro":"The end of Gavrikov – Van der Sterren. White brought a whole army to Black's king. Now comes a wave of sacrifices, leaving Black's king all alone.","moves":[{"q":"Your rook stands on the d-file. Capture the pawn in the center with it!","c":"28.Rxe5! The rook takes the pawn. If Black takes it with a rook, the g4 knight takes back."},{"c":"28…Nxf5. Black captures your knight."},{"q":"Take the knight back with your rook.","c":"29.Rxf5. The rook stands on the f-file and presses on the f7 pawn."},{"c":"29…Rxe4. Black takes the e4 pawn."},{"q":"The knight leaps into the center and joins the rook in attacking the f7 pawn.","c":"30.Ne5! Two pieces attack f7: the knight and the rook."},{"c":"30…Re1+. Black gives check."},{"q":"Step into the breathing window you made with h3.","c":"31.Kh2. The king is safe. Playing h3 back in the opening really paid off!"},{"c":"31…Nf6. The knight comes to defend the king."},{"q":"Sacrifice! Take the king's last bodyguard with your rook.","c":"32.Rxf6! The rook gives itself up to smash the fortress in front of the king."},{"c":"32…gxf6. The g-pawn disappears from in front of the king."},{"q":"Your c1 bishop waited all game. Now take the pawn and attack the queen!","c":"33.Bxh6! The bishop takes the pawn and attacks Black's queen."},{"c":"33…Qg8. The queen runs away."},{"q":"Knight check! Which pawn does it take along the way?","c":"34.Nxf7+! Check. The queen has to take the knight, or things get even worse."},{"c":"34…Qxf7."},{"q":"Don't forget: Black's rook on e1 is undefended!","c":"35.Rxe1. White has a queen, rook, and bishop against a queen and rook. Black's king is wide open, and Black soon resigned."}],"end":"The prettiest attacks happen when all your pieces come to help and then some of them sacrifice themselves. Remember: only sacrifice when you have more attackers by the king than defenders."},"g4storm":{"title":"King Still Home, Pawns Attack","intro":"Game Bologan – Prakash, Mamaia 1991. So far you castled first and attacked later. But who said the king has to castle right away? While your king waits in the middle, you can push your g and h pawns at Black's king without any risk—your king won't need them.","moves":[{"q":"Black's h6 pawn is a target for you. Which pawn starts the attack?","c":"10.g4! The pawn marches forward, getting ready for g5. Since your king hasn't castled there, it doesn't miss the g-pawn."},{"c":"10…Nh7. The knight drops back to guard the g5 square."},{"q":"The f1 knight is bored. Send it closer to Black's king.","c":"11.Ng3. The traveling knight arrives. From here it can jump to f5 or h5."},{"c":"11…Be6. Black wants to trade off your important b3 bishop."},{"q":"Bring your rook behind the g-pawn. You can do this even without castling!","c":"12.Rg1. The rook stands behind the pawn to help push it forward. If you had castled, the rook would be stuck on f1."},{"c":"12…d5. When your opponent attacks on the wing, answer in the center. Black plays the right idea."},{"q":"Your e4 pawn is attacked. Guard it with your queen.","c":"13.Qe2. The queen defends e4 and also clears room for queenside castling."},{"c":"13…Re8."},{"q":"Trade pawns in the center so your knight gets the e4 square.","c":"14.exd5. The e-file opens up and e4 is free for your knight."},{"c":"14…Bxd5."},{"q":"Jump your knight into the center onto a square guarded by the d3 pawn.","c":"15.Ne4! The knight stands tall in the center, protected by the d3 pawn. From here it eyes f6 and g5, close to Black's king."},{"c":"15…Bxb3. Black trades bishops after all."},{"q":"Take back. With which pawn? Think about your a1 rook.","c":"16.axb3. Now the a1 rook has an open a-file."}],"end":"Remember: if the center holds, you don't need to rush castling. Your g and h pawns can attack while your king waits to see which side is safer. In the next chapter you'll see where the king finally goes."},"ooo":{"title":"Long Castling and the Rook on g7","intro":"Continuing Bologan – Prakash. Black played …f6 and tucked their king away on h8. Your g and h pawns are ready. Now it's time to decide where your king goes.","moves":[{"q":"Send the second pawn into the attack.","c":"17.h4. The g and h pawns march together. You are getting ready for g5."},{"c":"17…Kh8."},{"q":"Develop your last bishop. Offer a trade to the a7 bishop.","c":"18.Be3. The a7 bishop aims at f2. Offering to trade it off is best."},{"c":"18…Bxe3."},{"q":"Take back.","c":"19.Qxe3. The queen stands in the middle and guards the queenside."},{"c":"19…Qd5. Black's queen attacks the b3 pawn."},{"q":"Your king is still in the center. Where will you hide it? Your pawns are charging on the kingside.","c":"20.O-O-O! Long castling. Your king steps away from its attacking pawns and the d1 rook jumps right into the game."},{"c":"20…Qxb3? Black's queen grabbed a pawn, but wandered far away from her own king."},{"q":"Their queen is far away. Strike with your pawn!","c":"21.g5! The pawn attacks h6 and f6 and opens the road for the g1 rook."},{"c":"21…f5. Black attacks your knight."},{"q":"Your knight is attacked. Don't run backward! Jump where it attacks the queen.","c":"22.Nc5! The knight attacks the b3 queen and eyes b7 and e6."},{"c":"22…Qb6."},{"q":"Smash open the pawns in front of the king.","c":"23.gxh6. The pawns protecting Black's king are broken, and the g1 rook sees all the way to the g7 pawn."},{"c":"23…Rad8."},{"q":"Your g1 rook sees all the way to g7. Crash right in!","c":"24.Rxg7. The rook stands right next to Black's king and attacks the h7 knight."},{"c":"24…e4."},{"q":"Bring in one more attacker. Your f3 knight attacks h7.","c":"25.Ng5. The knight attacks the h7 knight. Black's king is under fire from the rook, knight, and h6 pawn."},{"c":"25…Nxg5."},{"q":"Take back with the queen. Look how close she is to the king.","c":"26.Qxg5. The queen joins the rook."},{"c":"26…Ne5."},{"q":"A rook check finishes the game!","c":"27.Rh7+! The king has to take the rook, and then Qg7 is checkmate, backed up by the h6 pawn. Black resigned."}],"end":"The king waited in the center and went to the safe side: long castling away from its attacking pawns. Then the g and h pawns opened the door to Black's king, and the rook and queen rushed inside."},"fpawn":{"title":"The f-Pawn Attack","intro":"Game Tiviakov – De Vreugt, Dieren 2003. Even the f-pawn can attack! It is locked behind the f3 knight. Once you move the knight out of the way, the pawn charges forward and opens a highway for the rook straight to Black's king.","moves":[{"q":"Move the f3 knight out of the way so the f-pawn can march.","c":"10.Nh4! Now the f-pawn has an open road. And from h4, the knight watches f5 and g6."},{"c":"10…c6."},{"q":"When your f-pawn moves, Black's a7 bishop would aim straight at your king. Remove it!","c":"11.Bxa7. The a7 bishop was dangerous. Now nothing points at your king."},{"c":"11…Rxa7."},{"q":"Forward, pawn!","c":"12.f4! The pawn attacks e5, and the f1 rook waits right behind it."},{"c":"12…Ng6. The knight attacks both your h4 knight and your f4 pawn."},{"q":"Trade knights.","c":"13.Nxg6."},{"c":"13…hxg6."},{"q":"Capture the pawn. Which file does this open?","c":"14.fxe5! The f-file is open. Your f1 rook sees all the way to f7 and the f6 knight."},{"c":"14…dxe5."},{"q":"Bring your last knight into the game.","c":"15.Nf3. The knight attacks the e5 pawn."},{"c":"15…Bg4. Black pins the knight."},{"q":"The queen starts a trip toward the kingside.","c":"16.Qe1. The queen is heading for g3."},{"c":"16…Nd7."},{"q":"Bring the queen closer to Black's king!","c":"17.Qg3! The queen attacks the e5 pawn and stands near the king."},{"c":"17…Bxf3. Black takes your knight."},{"q":"Take back so you put a rook on the f-file.","c":"18.Rxf3. Now both your f3 rook and b3 bishop aim at the f7 pawn. Only the f8 rook and the king guard it."},{"c":"18…Nc5? The knight attacks your b3 bishop. But there are too many attackers on f7 now!"},{"q":"Capture on f7 with check!","c":"19.Bxf7+! The bishop sacrifices itself."},{"c":"19…Rxf7."},{"q":"Take the rook.","c":"20.Rxf7."},{"c":"20…Kxf7. The king takes the rook. Now White is down a piece… or are we?"},{"q":"Give check with your queen so you attack the c5 knight at the same time!","c":"21.Qf2+! A fork: check to the king and an attack on the c5 knight. The king has to move and the queen captures the knight. Black resigned."}],"end":"The f-pawn opened the road for the rook, and more attackers piled up on f7 than defenders. Also notice the queen fork at the end—the queen is the best forking piece on the board!"},"nf4":{"title":"Watch Out for Enemy Knights on f4","intro":"The traveling knight isn't only your idea. Black also sends knights over to the kingside. Their target is the f4 square right next to your king. Let's see how to answer it.","moves":[{"c":"11…Nh5. The knight is heading for f4. But it left f6 and stopped guarding the center."},{"q":"Your opponent's knight went to the edge of the board. An old recipe says: answer a wing attack by striking in the center.","c":"12.d4! Black's knight went to the edge, so you strike in the center. Your c3 pawn, f3 knight, and queen all back up the d4 pawn."},{"c":"12…Nhf4. The knight lands on f4. It looks scary, but it can't do much all by itself."},{"q":"Finish your own knight's trip. From which square does it guard e4 and eye h5?","c":"13.Ng3. The knight guards e4 and looks at f5 and h5."},{"c":"13…Qf6? The queen comes to back up the f4 knight. Players do this a lot, but it's a mistake—the queen stepped onto a square where a knight can attack her."},{"q":"Find a knight jump that attacks the queen.","c":"14.Nh5! The knight attacks the queen. If Black captures it with the f4 knight, Bg5 traps Black's queen."},{"c":"14…Qe7. The queen steps back."},{"q":"Both your bishop and knight attack the f4 knight. Start capturing with the bishop.","c":"15.Bxf4. The bishop takes first; the knight waits."},{"c":"15…Nxf4. Black's second knight takes back."},{"q":"Take the second knight too.","c":"16.Nxf4. Both dangerous knights are gone."},{"c":"16…exf4. A pawn takes back. Now it sits alone on f4, far from its friends. And the e5 pawn that held back your center is gone."},{"q":"The f4 pawn is all alone. Attack it with your queen.","c":"17.Qd2! The queen attacks the f4 pawn and your center can push forward with e5. Black's attack is over and you stand much better."}],"end":"When your opponent moves a knight from f6 to the edge, strike in the center with d4. And don't be scared of a knight on f4: count attackers and defenders, and trade it off."},"pin":{"title":"The Bg5 Pin: Pin It, Pile On, Smash It","intro":"A pin means a piece cannot move because something even more valuable stands behind it. The very first world champion, Steinitz, gave this tip: only pin the f6 knight after Black has castled kingside. Even great Anand forgot once—in 2018 he pinned Kramnik's knight too early, Black chased the bishop with g5 and h6, and won. In this chapter Black has already castled, so the pin works.","moves":[{"c":"5…O-O. Black castled early. The f6 knight now guards the king."},{"q":"Black has already castled. Pin the f6 knight!","c":"6.Bg5! The f6 knight cannot move because the queen stands behind it. If Black hadn't castled yet, they could chase the bishop with h6 and g5. After castling, those pawns sit in front of their king, so pushing them is dangerous."},{"c":"6…d6. Black calmly keeps developing. That is too slow!"},{"q":"A pinned knight is weak. Attack it with a second piece!","c":"7.Nd5! Two pieces attack the f6 knight: the bishop and the knight. You threaten to take on f6 and smash the king's house."},{"c":"7…h6. Black tries to chase the bishop away, but it's too late."},{"q":"Don't retreat! Take the knight with check.","c":"8.Nxf6+! The queen cannot take back because the g5 bishop would take her. The g7 pawn has to capture."},{"c":"8…gxf6. The pawn was forced away from in front of the king."},{"q":"Your bishop is attacked by two pawns. Where can it go to grab something along the way?","c":"9.Bxh6! The bishop grabs a pawn and attacks the f8 rook. Black's king has hardly any pawns left."},{"c":"9…Re8. The rook runs away."},{"q":"Bring in another attacker. The knight clears the way for your queen and aims for f5.","c":"10.Nh4! The queen can come to h5 or g4, and the knight to f5. Black's king has no pawns left to protect it."}],"end":"Three steps: pin it, add an attacker, smash the house. And the other way around: when your opponent wants to pin YOUR f3 knight, take away g4 with h3 before their bishop gets there."},"a7bishop":{"title":"The a7 Bishop Shoots at Nothing","intro":"Game Nunn – Olafsson, Middlesbrough 1982. Black's bishop stands on a7 looking at f2. But what if nothing is on that diagonal? Your dark-squared bishop avoids getting traded and turns to aim at Black's king.","moves":[{"q":"Everything is developed. Strike in the center.","c":"13.d4. The center gets moving."},{"c":"13…Bg4. The bishop pins your f3 knight."},{"q":"Push the pawn and chase the c6 knight away.","c":"14.d5. The pawn attacks the knight and closes the center. Now the a7 bishop aims at d4, where there's nothing to hit."},{"c":"14…Ne7."},{"q":"Ask the g4 bishop what it wants to do.","c":"15.h3. The bishop has to make up its mind."},{"c":"15…Bxf3. Black gives up a bishop for a knight."},{"q":"Take back.","c":"16.Qxf3. White has two bishops; Black has no light-squared bishop left."},{"c":"16…Nfg8. Black gets ready to play f5."},{"q":"Don't trade your c1 bishop for the a7 bishop. Put it where it can head to the long diagonal later.","c":"17.Bd2! The bishop avoids the trade. From c3 it will aim at e5 and g7, straight at Black's king."},{"c":"17…g6."},{"q":"Make your d5 pawn extra strong.","c":"18.c4. The d5 pawn is rock solid and the a7 bishop can't get into the game."},{"c":"18…f5?! Black strikes, but this opens diagonals for your bishops."},{"q":"Take the pawn.","c":"19.exf5."},{"c":"19…Nxf5."},{"q":"Trade knights.","c":"20.Nxf5."},{"c":"20…gxf5. There are holes in front of Black's king."},{"q":"Put your bishop on the long diagonal. Where is it looking?","c":"21.Bc3! The bishop aims through e5 all the way to g7 and h8, where the king stands. Meanwhile, the a7 bishop stares at empty air."}],"end":"One bishop attacks the king while the other sits on a7 with nothing to do. That is why you shouldn't trade your dark-squared bishop for the a7 bishop when nothing is threatened on that diagonal. In the next chapter you'll see how the bishops decided the game."},"elephants":{"title":"Sacrifice the Rook, Let the Bishops Shoot","intro":"The end of Nunn – Olafsson. Your c3 bishop aims at h8 and your second bishop on c2 aims at f5. The only thing blocking them is the e5 pawn. What if you take it with a rook?","moves":[{"q":"The e5 pawn blocks your c3 bishop's diagonal. Capture it!","c":"28.Rxe5! The rook sacrifices itself to clear the highway for the bishop."},{"c":"28…dxe5."},{"q":"Take back with the bishop. What does it attack?","c":"29.Bxe5. The bishop attacks the g7 rook, which is pinned to the h8 king. Black is up a rook, yet completely helpless."},{"c":"29…b6."},{"q":"Push the pawn forward. It will attack the e7 knight.","c":"30.d6! The pawn attacks the knight and opens a path for your queen."},{"c":"30…Nc6. The knight attacks your bishop."},{"q":"Your bishop is attacked. Step back so it still attacks g7.","c":"31.Bf6. The g7 rook is still pinned."},{"c":"31…Qe6."},{"q":"Take the rook!","c":"32.Bxg7+."},{"c":"32…Rxg7."},{"q":"Your queen has an open diagonal. What can she take?","c":"33.Qxc6. Down goes the knight."},{"c":"33…bxc5."},{"q":"Queen check!","c":"34.Qa8+."},{"c":"34…Rg8."},{"q":"Capture the bishop that spent the whole game shooting at nothing.","c":"35.Qxa7. The a7 bishop fell without ever doing a single thing."},{"c":"35…Rxg3+."},{"q":"Step out of check.","c":"36.Kh2."},{"c":"36…Qe5."},{"q":"Take the pawn and guard the e7 square.","c":"37.Qxc5. The queen guards the d6 pawn, which is ready to promote, and Black resigned."}],"end":"Sacrificing the rook on e5 opened the bishop's diagonal straight to the king. When your opponent's bishop sits out of the game on a7, it often feels like you are playing a whole piece up: your piece attacks while theirs just watches."},"d5":{"title":"When Black Strikes with …d5","intro":"Game Oratovsky – Lev, Ramat Aviv 2000. Black pushed the d-pawn first to d6 and now again to d5. Two moves to go one road! That wastes time, and White punishes it by attacking the e5 pawn and the king.","moves":[{"c":"8…d5?! The pawn reaches d5 only on the second try."},{"q":"Take the pawn. The e-file will open.","c":"9.exd5. The e5 pawn no longer has a friend on d6 to defend it."},{"c":"9…Nxd5."},{"q":"First, king to safety.","c":"10.O-O."},{"c":"10…Ba7."},{"q":"Your d2 knight has a free square in the center. Jump there!","c":"11.Ne4! The knight stands in the center. From here it can hop to g5, right near Black's king."},{"c":"11…Kh8."},{"q":"Put a rook on the open e-file. What will it aim at?","c":"12.Re1. The rook aims down the open file at the e5 pawn."},{"c":"12…f5? The pawn attacks your knight. But pushing it opens a path toward Black's own king."},{"q":"Your knight is attacked. Don't run backward—jump forward!","c":"13.Neg5! The knight stands close to the king and attacks e6, f7, and h7."},{"c":"13…f4."},{"q":"Your second knight grabs the undefended pawn in the center!","c":"14.Nxe5! If Black takes the knight, the e1 rook takes back and keeps attacking."},{"c":"14…Nxe5."},{"q":"Take back with the rook.","c":"15.Rxe5. The rook sits in the center and Black's king has few defenders."},{"c":"15…c6."},{"q":"Bring in the queen! Together with the g5 knight she threatens checkmate. On which square?","c":"16.Qh5! Threatening Qxh7 mate. The g5 knight guards the h7 square."},{"c":"16…h6. Black blocks h7 and attacks the knight."},{"q":"Knight check! Which square can it jump to so it attacks Black's queen too?","c":"17.Nf7+! Check to the king and an attack on the d8 queen at the same time. That's a fork!"},{"c":"17…Rxf7. The rook had to take the knight."},{"q":"Take the rook with your queen.","c":"18.Qxf7. White is up a whole rook."},{"c":"18…Bxf2+. Black tries one last trick."},{"q":"Take the bishop with your king.","c":"19.Kxf2."},{"c":"19…Qh4+. Check."},{"q":"Where does the king step to safety?","c":"20.Kg1."},{"c":"20…Bxh3. Black takes one more pawn."},{"q":"Your b3 bishop has been aiming at d5 the whole time. Take the knight!","c":"21.Bxd5. White is ahead a rook and a piece. Black resigned."}],"end":"A pawn that takes two moves to reach d5 gives the opponent a gift: time. White used that time to open the e-file, send the knights to the king, and win with a fork."},"d5early":{"title":"Too-Early …d5: The Queen Fork","intro":"In the chapter \"When Black Strikes with …d5\", Black castled first. What if they strike one move earlier, with their king still in the center? Then you punish them right away. The pair you know from the Evans Gambit will help you: the queen on b3 and the bishop on c4.","moves":[{"c":"5…d5?! Black struck too soon. Their king is still standing on e8."},{"q":"The pawn attacked both your bishop and your e4 pawn. Capture it.","c":"6.exd5."},{"c":"6…Nxd5. The knight takes back."},{"q":"Line your queen up behind your bishop. Which piece will they attack together?","c":"7.Qb3! Queen and bishop attack the d5 knight. Plus, the queen eyes the b7 pawn. Suddenly Black has lots of problems."},{"c":"7…Nce7? Black guards the d5 knight with the other knight. Looks sensible, but the knight left c6 and opened the queen's road to the king."},{"q":"The king is in the center and nobody guards the c5 bishop. Find a queen check that attacks the bishop too.","c":"8.Qb5+! A queen fork: check to the king and an attack on the c5 bishop."},{"c":"8…c6. Black blocks the check and attacks your queen. It won't help."},{"q":"Take the undefended bishop.","c":"9.Qxc5. You are up a whole piece."}],"end":"Even after the better defense 7…O-O you win material: 8.Bxd5 Na5 9.Qd1 Qxd5, and then 10.b4 attacks both the bishop and the knight at once. Striking with …d5 is only good for Black after castling."},"endgame":{"title":"Italian Endgame: King to the Center, Knight to c4","intro":"Game Tiviakov – Nijboer, Plovdiv 2008. The queens are off the board and the position looks the same for both sides. But it isn't! Your king is already in the center because you didn't castle, and your d2 knight has the lovely c4 square. Black's c6 knight can't reach a square like that because your c3 pawn blocks it.","moves":[{"q":"Which square is best for your knight? Show it the way.","c":"19.Nd2! The knight is headed for c4. From there it will attack a5, b6, d6, and e5."},{"c":"19…Rfe8."},{"q":"Your c2 bishop has nothing to do. Move it to a better diagonal.","c":"20.Bd3. The bishop aims at b5 and c4."},{"c":"20…g6."},{"q":"Take the f5 and h5 squares away from Black's knight.","c":"21.g4. The pawn guards f5 and leaves Black's knights with very little room."},{"c":"21…Re7."},{"q":"Attack the c6 knight.","c":"22.Bb5. The bishop attacks the knight."},{"c":"22…Nb8. The knight drops all the way back."},{"q":"Prepare the a3–f8 diagonal for your c1 bishop.","c":"23.b3. Now the c1 bishop can go to a3."},{"c":"23…c6? The pawn chases the b5 bishop away. It was better to put the bishop on c5 to block your other bishop's a3–f8 diagonal."},{"q":"Your bishop is attacked. Where does it step back so it attacks Black's bishop?","c":"24.Bc4! The bishop faces off against the e6 bishop."},{"c":"24…Nf8."},{"q":"Place your second bishop on the open diagonal.","c":"25.Ba3! The bishop attacks the e7 rook and the f8 knight."},{"c":"25…Red7. The rook takes the d7 square, which Black's knight wanted."},{"q":"Put your rook on the open d-file.","c":"26.Rhd1. The rooks face each other on the d-file."},{"c":"26…Bxe3."},{"q":"Take back. With which pawn? You want to guard the f4 square.","c":"27.fxe3! The pawn guards f4, where Black's knight would love to jump."},{"c":"27…Kg7? The king steps onto the a3 bishop's diagonal. Now comes a trade with check."},{"q":"Take the knight with check!","c":"28.Bxf8+! A trade with check."},{"c":"28…Rxf8."},{"q":"Trade off the second bishop too.","c":"29.Bxe6."},{"c":"29…fxe6."},{"q":"Finally, put the knight on its dream square!","c":"30.Nc4! The knight attacks both the a5 and e5 pawns. A few moves later, White actually captured the a5 pawn."}],"end":"After trading queens, the board only looks equal. Your king is already in the center, your d2 knight has the great c4 square, and Black's knight sits on b8 with no good square. Tiviakov went on to win a pawn and, thanks to his active king, the whole game."},"mason":{"title":"Combination of the Century: Mason – Winawer","intro":"Game Mason – Winawer, Vienna 1882. This is one of the oldest games of the quiet Italian. At the end, White played a dazzling combination: sacrificing a rook, then a second rook, and finally winning the queen. Can you find his moves?","moves":[{"q":"Bring your queen closer to Black's kingside.","c":"39.Qh5. The queen attacks the h6 pawn and peeks into Black's camp."},{"c":"39…Rf6."},{"q":"Sacrifice! Take the g5 pawn with your rook.","c":"40.Rxg5! The rook sacrifices itself. If the pawn takes it, your queen reaches h7."},{"c":"40…hxg5."},{"q":"Queen check! Which square?","c":"41.Qh7+. Check. Black has to block the check with a knight."},{"c":"41…Nd7."},{"q":"Capture the knight that blocked the check.","c":"42.Bxd7. The bishop takes the knight and threatens check again."},{"c":"42…Qg8! The best defense. The queen offers a trade."},{"q":"The prettiest move of the game! Sacrifice your second rook with check.","c":"43.Rb7+!! The rook sacrifices itself. If the king takes it, it steps right into the bishop's line."},{"c":"43…Kxb7. The king takes the rook."},{"q":"Bishop check! Look at what opens up behind the bishop.","c":"44.Bc8+!! The bishop gives check and clears the path from the h7 queen to Black's g8 queen. Next move the queen takes the queen. Black resigned."}],"end":"This is called a discovered attack: one piece steps out of the way and opens the road for another piece behind it. The bishop gave check while the queen behind it attacked Black's queen. Your opponent cannot save two things at once."},"twok":{"title":"A Bishop in a Spanish Coat","intro":"Black doesn't have to play 3…Bc5. Often they bring the knight to f6 and place the bishop modestly on e7. You still build the same quiet house. And when your opponent chases your bishop, it escapes along a road well known to Ruy Lopez (Spanish) players.","moves":[{"c":"3…Nf6. The Two Knights Defense. The knight attacks your e4 pawn."},{"q":"Defend the e4 pawn calmly.","c":"4.d3. A solid center. You know the sharp 4.Ng5 attack from the Fried Liver study; here we learn the quiet way."},{"c":"4…Be7. The bishop sits modestly and guards the g5 square."},{"q":"King to safety.","c":"5.O-O."},{"c":"5…O-O."},{"q":"Rook behind the e4 pawn. Remember why?","c":"6.Re1. It guards e4 and clears the f1 square for the traveling knight."},{"c":"6…d6."},{"q":"Prepare the c2 escape square for your bishop.","c":"7.c3. The pawn guards d4 and opens the path to c2 for your bishop."},{"c":"7…Na5. The bishop hunt begins!"},{"q":"A pawn sits on a2, so there's no home there. And on b3 the knight would trade off your bishop. Where to?","c":"8.Bb5! The bishop takes the scenic route home. On b3 the knight would take it, but on b5 the knight can't reach it."},{"c":"8…a6. A pawn keeps chasing it."},{"q":"Step back one square.","c":"9.Ba4. One more step."},{"c":"9…b5. Chased again."},{"q":"Now tuck into safety on the square your c3 pawn prepared.","c":"10.Bc2! The bishop is safe at home and nobody traded it off. For now it hides behind the d3 pawn. Once you play d4 and open the center, it will aim straight at h7 next to Black's king."},{"c":"10…c5. Black gained space on the queenside."},{"q":"The traveling knight sets off.","c":"11.Nbd2. You know the rest: Nf1, Ng3, and then d4."}],"end":"The bishop walked the c4–b5–a4–c2 path just like in the Spanish Game (Ruy Lopez). Your opponent gained some queenside space, but your bishop stayed on the board waiting for its big moment."},"qf6":{"title":"Queen Out Too Early: 4…Qf6","intro":"Many players love bringing the queen out right at the start. A queen on f6 aims together with the bishop at your f2 square and looks scary. But she is standing on the square meant for the g8 knight, and your pawns will chase her around.","moves":[{"c":"4…Qf6?! Queen and bishop aim at f2. But the g8 knight lost its best square."},{"q":"There is no knight on f6, so nothing attacks your e4 pawn. You can strike the center right away.","c":"5.d4! In the quiet Italian you wait with this move. Here you don't need to wait: nobody attacks e4, and the c5 bishop has to deal with your threat."},{"c":"5…exd4?! Black takes. Retreating the bishop to b6 was better."},{"q":"The queen stands right in your pawn's path. Chase her away!","c":"6.e5! The pawn attacks the queen. The knight cannot take it: after 6…Nxe5 comes 7.Qe2, pinning the e5 knight to the king."},{"c":"6…Qg6. The queen runs away and eyes the g2 pawn."},{"q":"Take the pawn back and attack the bishop at the same time.","c":"7.cxd4. The center is yours and the c5 bishop is attacked."},{"c":"7…Bb4+. Check."},{"q":"Block the check by developing a knight. Your g2 pawn is left unguarded, and that's okay.","c":"8.Nc3! The knight develops. You leave the g2 pawn for the queen on purpose—it is poisoned!"},{"c":"8…Qxg2? The greedy queen grabs the pawn and attacks your rook."},{"q":"The queen sneaked deep into your camp. Attack her with your rook.","c":"9.Rg1. The queen has only one safe square left."},{"c":"9…Qh3. The queen hides on h3."},{"q":"Sacrifice your bishop with check on the square it has been aiming at since move three.","c":"10.Bxf7+! If the king takes the bishop, a knight fork comes next."},{"c":"10…Kxf7. The king takes."},{"q":"Find a knight check that attacks the queen too.","c":"11.Ng5+! A fork: check to the king and an attack on the h3 queen."},{"c":"The king runs away."},{"q":"Take the queen.","c":"12.Nxh3. The queen is yours."}],"end":"A queen that comes out too early becomes a target. You chase her around while developing your pieces and building the center. Even if the king hadn't taken the f7 bishop, it would lose castling and your attack would roll on."},"qe7":{"title":"Black Holds the Center: 4…Qe7","intro":"A careful opponent won't bring the knight to f6, and instead backs up the e5 pawn with the queen. Then they don't have to take when you play d4. In that case you keep a huge center and chase their bishop. That is how Alekhine already played against Tarrasch.","moves":[{"c":"4…Qe7. The queen guards the e5 pawn. Nothing attacks e4."},{"q":"Nobody attacks your e4 pawn. So what can you play right away?","c":"5.d4! Same rule as with the queen on f6: when there is no knight on f6, you don't need to wait with d4."},{"c":"5…Bb6. Black didn't take. If they took with 5…exd4, you castle. And after the greedy 6…dxc3 7.Nxc3, all your pieces are in the game and your knight jumps to d5 right at the queen."},{"q":"Your center stands tall. What now?","c":"6.O-O. The king is safe."},{"c":"6…d6. Black opens the c8 bishop, which wants to go to g4."},{"q":"Black's bishop wants to pin your f3 knight, which defends the d4 pawn. Take that square away.","c":"7.h3. Our familiar breathing window. The f3 knight guards your center and nobody can pin it."},{"c":"7…Nf6. The knight attacks the e4 pawn."},{"q":"Defend the e4 pawn with your rook.","c":"8.Re1."},{"c":"8…O-O."},{"q":"The b6 bishop doesn't have much room. Send your edge pawn after it.","c":"9.a4! Threatening a5, leaving the bishop with nowhere to run. You know this hunt from the Evans Gambit Declined."},{"c":"9…a6. Black makes an escape square on a7 for the bishop."},{"q":"Develop your last knight. A pawn is on c3, and leave d2 free for your bishop.","c":"10.Na3. The knight will continue to c2 or c4. You have a big e4 + d4 center and more space, while Black's pieces are cramped."}],"end":"When Black doesn't take on d4, your center stays standing. Then just back it up (h3, Re1) and chase the b6 bishop with your edge pawn."},"legal":{"title":"Légal's Trap","intro":"A famous trap over 250 years old. It teaches you that a pin to the queen is not the same as a pin to the king: a knight pinned to a queen IS allowed to move! And sometimes that wins the game.","moves":[{"q":"Develop your second knight. Here it can go to c3 because your c-pawn is still at home.","c":"4.Nc3. The knight guards the d5 square. In a moment you'll see why that matters."},{"c":"4…Bg4. The bishop pins the f3 knight to the queen."},{"q":"Ask the bishop where it wants to go.","c":"5.h3. The bishop has to choose: trade itself off or step back."},{"c":"5…Bh5? The bishop keeps the pin going. But nobody protects it on h5, and that is a mistake."},{"q":"Your knight is only pinned to the queen, so it is allowed to move. Take the pawn with it!","c":"6.Nxe5! White offers the queen. If Black takes the e5 knight with their knight, your queen takes the unguarded h5 bishop and you are up a pawn."},{"c":"6…Bxd1?? Black grabs your queen and thinks they won."},{"q":"Remember where your c4 bishop has been aiming the whole time?","c":"7.Bxf7+! Check. The e5 knight guards the bishop, so the king cannot take it."},{"c":"7…Ke7. The only square."},{"q":"Deliver checkmate with the knight from c3!","c":"8.Nd5 mate! Two knights and a bishop caught the king, even though Black is up a queen."}],"end":"Three minor pieces delivered checkmate because Black grabbed the queen without checking what threatened their king. Before every capture, ask yourself: what is my opponent threatening with this move?"},"nd4":{"title":"Watch Out for 3…Nd4: A Pawn with a Hook","intro":"Sometimes Black jumps a knight to d4 and leaves the e5 pawn unguarded. It looks like a free gift. Whenever someone offers you a gift, ask: why are they giving this to me?","moves":[{"c":"3…Nd4!? The knight moves a second time in the opening and nobody guards the e5 pawn. It is bait."},{"q":"Don't take the e5 pawn. Instead, remove the knight that came to visit.","c":"4.Nxd4. You traded your knight for a knight that moved twice. You gained time."},{"c":"4…exd4. The pawn takes back."},{"q":"And now king to safety.","c":"5.O-O. You have a developed bishop, a safe king, and a pawn in the center. Black hasn't developed a single piece yet."}],"end":"If you took 4.Nxe5, Black plays 4…Qg5! The queen attacks both the e5 knight and the g2 pawn at the same time. After a careless 5.Nxf7?, the queen takes on g2 and checkmate soon follows. A free pawn often hides a hook."}}},"tactics":{"name":"Tactics – Soviet Chess Primer","intro":"A short guide to tactics from the famous Soviet chess textbook: pins, forks, skewers, smothered mate, a series of checks, and the rule of the square. Each topic has a position from the book. You can find practice puzzles in Woodpecker under the Tactics from the Primer set.","chapters":{"pin1":{"title":"The pin: a pinned pawn does not defend","intro":"A pin happens when a piece cannot move because something more valuable is standing behind it, like the king. Look at the diagonal from your bishop on e5 all the way to the black king on h8. The g7 pawn is standing on it. That pawn is pinned: if it moved, the bishop would put the king in check. A pinned piece pretends to defend, but really it defends nothing at all.","moves":[{"q":"The g7 pawn is pinned. So you can capture the h6 pawn, even though it looks like g7 protects it.","c":"1.Qxh6+! The g7 pawn cannot capture because it is pinned by the e5 bishop."},{"c":"1…Kg8. The king has to step aside."},{"q":"Queen and bishop working together. Deliver checkmate!","c":"2.Qxg7#. The queen on g7 is protected by the e5 bishop. Checkmate!"}],"end":"Before every move, check which of your opponent's pieces are pinned. A pinned defender cannot protect anything, so you can capture even where it looks dangerous."},"pin2":{"title":"The pin: attack the pinned piece","intro":"Your rook on g4 is looking down the g-file straight at the black king. Between them stands the g7 bishop. The bishop is pinned: it cannot move away, or the rook would give check to the king. A pinned piece is tied to a post. When you attack it, it cannot run away.","moves":[{"q":"The g7 bishop cannot run away. Attack it with a pawn!","c":"1.f6! The pawn attacks the bishop. The bishop is pinned, so it cannot escape."},{"c":"1…Kf8. The king stepped off the g-file and unpinned the bishop. Too late, though!"},{"q":"Capture the bishop!","c":"2.fxg7+. White wins a whole bishop, and the g7 pawn is almost ready to promote."},{"c":"2…Kg8. The black king has to come back and guard the promotion square."}],"end":"When your opponent's piece is pinned, don't wait. Add another attacker, best of all a pawn. A pinned piece cannot run away and will be lost."},"fork":{"title":"Pawn fork","intro":"From the game Belavenets – N.N., 1936. A fork is when one piece attacks two enemy pieces at the same time. Your opponent can only save one of them. The cheapest fork is a pawn fork: a pawn is worth the least, so your opponent will lose a much bigger piece, like a knight or bishop. Look at Black's knight on e6 and bishop on g6. They are one square apart.","moves":[{"q":"Black's knight on e6 and bishop on g6 stand side by side on the 6th rank. Which pawn wants to jump right between them?","c":"1.f4! You threaten f5, forking both the knight and the bishop."},{"c":"1…f5. Black stops your pawn with his own pawn."},{"q":"The f5 pawn blocked the road. Attack it with another pawn!","c":"2.g4! The pawn attacks f5. Whether Black takes or pushes, your f4 pawn will move forward."},{"c":"2…fxe4. Black captured the pawn."},{"q":"Now the road is clear. Play the fork!","c":"3.f5! The pawn attacks both the e6 knight and the g6 bishop. Black is going to lose a piece."}],"end":"A fork means one piece attacking two. When enemy pieces stand one square apart, look for a pawn that can step between them. If your opponent blocks the way, knock down the blocker with another pawn."},"skewer":{"title":"Skewer: attacking through a piece","intro":"Your a7 pawn is one step from promoting, but your own rook on a8 is blocking its way. If the rook just moves away, Black's rook on a5 will take the pawn. A trick called a skewer (like an X-ray) will help: you attack a piece, and behind it stands another piece that you will capture next.","moves":[{"q":"Clear the way for your pawn. Where should the rook go so you also threaten promotion?","c":"1.Rh8! You threaten a8=Q. If Black's rook takes the pawn, it lands on the same rank as its king."},{"c":"1…Rxa7. Black took the pawn. Now the f7 king and a7 rook are on the 7th rank together."},{"q":"The king and rook are on the same rank. Give check so you attack the rook right through the king!","c":"2.Rh7+! The king must move out of the way, leaving the a7 rook open."},{"c":"2…Ke6. The king stepped aside."},{"q":"Take the rook!","c":"3.Rxa7. White wins a rook and the game is won."}],"end":"Skewer: you attack a more valuable piece (like the king), and when it moves out of the way, you capture the piece standing behind it. Always look for it when two enemy pieces line up."},"smother":{"title":"Smothered mate","intro":"From the game Atkins – Gibson, Southport 1924. Black's king on h8 is surrounded by its own pieces. It has nowhere to run. All it takes to beat a king like that is one check from a knight. It is called a smothered mate: the king is smothered by its own pieces.","moves":[{"q":"Sacrifice your queen to fill up the king's last empty square.","c":"1.Qg8+!! The king cannot take the queen because the b3 bishop protects her. The rook has to take."},{"c":"1…Rxg8. The rook filled the g8 square. Now the king is completely walled in."},{"q":"Now bring in the knight!","c":"2.Nf7#. Smothered mate! The king has nowhere to go, and nobody can take the knight."}],"end":"When the king is tucked in the corner with its own pieces around it, look for a knight check. Sometimes you need to sacrifice a piece first to fill the king's last escape square."},"checks":{"title":"Check after check to checkmate","intro":"From the game Tolush – Randviir, Pärnu 1947. A check is a strong move because your opponent must answer it right away and has no time for anything else. When one check follows another, you can lure the king into a checkmate trap. Black's king on f6 is out in the middle, surrounded by your pieces.","moves":[{"q":"Give check with the d1 rook and let Black capture your e5 rook.","c":"44.Rd6+! The king has nowhere to run. Black could block with the knight on e6, but it would fall right away. So the king takes the e5 rook."},{"c":"44…Kxe5. The king marched even farther forward."},{"q":"Another check! Jump the knight so the king has to go to f5.","c":"45.Nf7+. The king must go to f5 because the f3 pawn guards e4."},{"c":"45…Kf5."},{"q":"And now checkmate with a pawn!","c":"46.g4#. The pawn delivered checkmate! The king is trapped by the rook, knight, and pawns."}],"end":"A series of checks gives your opponent no time to breathe. Always look at every check you have. Sometimes you sacrifice a piece to bring the king right where you can checkmate it."},"square":{"title":"The rule of the square","intro":"Can Black's king catch your pawn? You don't have to count move by move! Picture a square in your head: one side goes from the pawn to its promotion square, and the square stretches out just as wide toward the king. If the king is inside the square, it catches the pawn. If it is outside, it can never catch it. Careful: a pawn on h2 can jump two squares, so its square is counted as if it stood on h3.","moves":[{"q":"Black's king on b6 is just outside the square. Which pawn move lets you get away?","c":"1.h4! The pawn jumped two squares. The square goes from h4 to d8, and the b6 king is outside it."},{"c":"1…Kc5. The king starts chasing."},{"q":"Keep going!","c":"2.h5. The square shrank, and the c5 king is still outside it."},{"c":"2…Kd6."},{"q":"Keep pushing.","c":"3.h6."},{"c":"3…Ke7."},{"q":"One more step.","c":"4.h7."},{"c":"4…Kf7. The king arrived one move too late."},{"q":"Promote the pawn to a queen!","c":"5.h8=Q. A brand-new queen! The king couldn't make it in time."}],"end":"Rule of the square: draw a square from the pawn to the promotion square. If the enemy king is inside the square (or steps in on its turn), it catches the pawn. If it is outside, the pawn promotes. A pawn on the 2nd rank counts as if it were one square ahead."},"unfork1":{"title":"Beating a fork 1: defend both pieces","intro":"Black's queen on f5 is attacking both your b1 rook and your f3 knight at the same time. That's a fork. But don't give up! There are eight clever ways to fight back against a fork. Way 1: find a single move that defends both attacked pieces at once.","moves":[{"q":"Find a move that leaves both the b1 rook and the f3 knight defended.","c":"1.Qd1! From d1, the queen defends the b1 rook along the 1st rank and the f3 knight along the diagonal. You lose nothing! Playing 1.Kg2? Qxb1 or 1.Rxb7? Qxf3 would lose a piece."},{"c":"1…Qe4. Black keeps trying, but everything is safe."}],"end":"Way 1 to beat a fork: find one move that protects both attacked pieces at the same time."},"unfork2":{"title":"Beating a fork 2: escape with check","intro":"Black's knight on c2 is attacking both your e3 queen and your a1 rook. If the queen just runs away, the knight will take the rook. Way 2: move one attacked piece away with check. Your opponent has to deal with the check, giving you time to save the second piece.","moves":[{"q":"Where can your queen go while giving check?","c":"1.Qe6+! The queen escaped and gave check. Black has no time to take the rook."},{"c":"1…Kh8."},{"q":"The king stepped aside. Now save the a1 rook.","c":"2.Rad1. The rook is safe, and the c2 knight is now stuck alone in your camp. If you had played 1.Qf3?, Nxa1 would win your rook."},{"c":"2…c6."}],"end":"Way 2 to beat a fork: move an attacked piece away with check. The check buys you time to save the other piece."},"unfork3":{"title":"Beating a fork 3: one defends the other","intro":"Black's queen on d5 is attacking both your b3 rook and your g5 knight. Way 3: move one of the attacked pieces to a safe square where it also protects the other piece.","moves":[{"q":"Where can the rook go so it is safe and also defends the g5 knight?","c":"1.Rg3! The rook escaped from b3 and now protects the g5 knight. It looks like 1.Qe3 defends both too, but after 1…Rce8 Black's rook attacks the queen and something still drops."},{"c":"1…Rfe8. Both of your pieces are safe."}],"end":"Way 3 to beat a fork: move one attacked piece so that it defends the other one."},"unfork4":{"title":"Beating a fork 4: escape with a threat","intro":"Black's knight on c2 is attacking your e3 queen and your a1 rook. Way 4: move one attacked piece away while creating a threat of your own. Your opponent has to answer your threat, and you win time.","moves":[{"q":"Where can the queen move to attack something of Black's?","c":"1.Qf3! The queen escaped and attacked the a8 rook. If Black takes your rook with 1…Nxa1?, then 2.Qxa8 wins for White."},{"c":"1…Rb8. Black had to save the rook."},{"q":"The rook ran away. Now attack the c2 knight.","c":"2.Bd3! The bishop attacks the c2 knight."},{"c":"2…Nxd4. The knight escaped and grabbed a pawn, but your a1 rook is saved."}],"end":"Way 4 to beat a fork: run away while making a threat. When your opponent has to stop your threat, they don't have time to take your piece."},"unfork5":{"title":"Beating a fork 5: sacrifice your way out","intro":"Black's bishop on b4 is attacking both your d2 queen and your a5 rook. The bishop is guarded by the d5 knight. Way 5: sometimes you can break out of a fork with a sacrifice. Remove the defender of the piece doing the forking!","moves":[{"q":"Who is guarding the b4 bishop? Remove that defender!","c":"1.Rxd5! The rook captured the knight that was defending the b4 bishop."},{"c":"1…Qe7."},{"q":"Black's queen tries to get away. How do you save your rook and win the bishop too?","c":"2.Rd7!! Another sacrifice! The queen has to take, leaving the b4 bishop undefended."},{"c":"2…Qxd7. Now you capture the b4 bishop and get two minor pieces for a rook – a great trade!"}],"end":"Way 5 to beat a fork: sacrifice your way out. Remove the defender of the forking piece so it falls."},"unfork6":{"title":"Beating a fork 6: pin the forker","intro":"Black's d4 pawn is attacking both your c3 queen and your e3 knight. Way 6: pin the piece that is giving the fork! Once it cannot move, it cannot take anything. Look at what is standing behind the d4 pawn on the same rank.","moves":[{"q":"What is standing behind the d4 pawn on the 4th rank? Put your queen where the pawn cannot capture.","c":"1.Qc4! The queen attacks the d4 pawn, and behind it on the 4th rank stands Black's queen on h4. The pawn is pinned: if it took 1…dxe3?, then 2.Qxh4 wins Black's queen! Playing 1.Qd2? dxe3 would lose the knight."},{"c":"1…Bh7. Black's bishop stepped out of the way."},{"q":"Now save your knight and attack the d4 pawn with it.","c":"2.Nc2! The knight escaped and attacked the d4 pawn again."},{"c":"2…Qf4. Black defends the pawn, but White takes it with 3.Nxd4 – material is equal and the fork is gone."}],"end":"Way 6 to beat a fork: pin the forking piece. A pinned piece cannot capture because it would expose something even more valuable."},"unfork7":{"title":"Beating a fork 7: desperado","intro":"Black's knight on e4 is attacking your c3 queen and your g3 rook. You cannot save both. Way 7: desperado! A piece that is doomed anyway tries to sell itself for the highest price – grabbing something before it goes down.","moves":[{"q":"The g3 rook is a goner. What can it take before it falls?","c":"1.Rxg6+! Since the rook was going to be lost anyway, it took a bishop – and with check! Playing 1.Qb3? or 1.Bg5? Nxg3+ would lose the rook for nothing."},{"c":"1…hxg6. If Black's king had moved (1…Kf7 or 1…Kf8), then 2.Qg7+ would lead to a quick checkmate."},{"q":"Now save the queen.","c":"2.Qb3. The queen is safe. White traded a rook for a bishop, but Black's king is wide open now and White's pieces stand much better."},{"c":"2…Ndc5. The game goes on and White has the better position."}],"end":"Way 7 to beat a fork: desperado. When a piece cannot be saved, make it capture something first – best of all with check!"},"unfork8":{"title":"Beating a fork 8: escape with a mate threat","intro":"Black's knight on e3 is attacking your c2 queen, your f1 rook, and your c4 bishop all at once. It looks terrible! Way 8: move an attacked piece away while threatening checkmate. Your opponent has to save their king and won't have time to take your pieces.","moves":[{"q":"Where can the queen go to threaten checkmate on g7? Hint: the f7 pawn is pinned.","c":"1.Qg6!! The queen threatens 2.Qxg7 checkmate (protected by the c3 bishop). The f7 pawn cannot take her because it is pinned to the g8 king by the c4 bishop! Moves like 1.Qd3?, 1.Qe2?, or 1.Qf2? would lose the rook or bishop to the knight."},{"c":"1…Nf5. The knight hurried back to defend g7. Otherwise (for example 1…d5), 2.Qxg7 is checkmate."},{"q":"The knight guards g7. Give check and capture something.","c":"2.Qxf7+! The queen took a pawn with check."},{"c":"2…Kh8."},{"q":"Which black piece is undefended now?","c":"3.Qxd7. The queen captured the bishop too. White won a piece and keeps attacking."},{"c":"3…Qc6. Black wants to trade queens, but White is a whole piece ahead."}],"end":"Way 8 to beat a fork: escape with a checkmate threat. When your opponent has to rescue their king, they can't take your pieces. Victory snatched from the jaws of defeat!"},"unpin1":{"title":"Beating a pin 1: pin the pinner","intro":"Black's bishop on c5 has pinned your d4 queen to your g1 king. The d7 knight protects the bishop, so your queen cannot take it, and she cannot move out of the pin. Way 1 to beat a pin: pin the piece that is doing the pinning!","moves":[{"q":"Is Black's c5 bishop on the same file as Black's king? Pin it!","c":"1.Rc2! The rook pinned the c5 bishop to the c8 king. If the bishop takes your queen, Black's king would be in check – which is illegal. Your queen is saved! Watch out for 1.Rc1?, because Qxc1+ wins the rook."},{"c":"1…b6. Black defends the bishop, and White has the better game."}],"end":"Way 1 to beat a pin: pin the pinner. When your opponent's bishop is pinned too, it cannot capture your piece."},"unpin2":{"title":"Beating a pin 2: block the pin","intro":"Black's bishop on f7 has pinned your c4 knight to your a2 king. If Black plays b5, the knight won't be able to run away. Way 2 to beat a pin: put a piece or a pawn in between.","moves":[{"q":"Put a pawn between the knight and the king.","c":"1.b3! The pawn blocked the pin. Now the c4 knight is free to move again. If you had played 1.Kb3?, b5 would win your knight."},{"c":"1…Bd5. Black keeps attacking, but now you can save your knight."}],"end":"Way 2 to beat a pin: block it. Placing a piece or pawn between the pinner and the king breaks the pin."},"unpin3":{"title":"Beating a pin 3: sacrifice your way out","intro":"Black's bishop on g6 has pinned your d3 rook to your c2 king. Both the c5 knight and the d6 queen are attacking the rook. Way 3 to beat a pin: sacrifice a piece to capture the one doing the pinning.","moves":[{"q":"Which black piece is pinning the d3 rook? Capture it!","c":"1.Qxg6! The queen took the pinning bishop. The pin is gone, and now the d3 rook attacks Black's queen! Playing 1.Nc1? Nxd3 would lose the pinned rook."},{"c":"1…hxg6. Black took the queen. But now…"},{"q":"The d3 rook is no longer pinned. What can it take?","c":"2.Rxd6! Free from the pin, the rook captures Black's queen."},{"c":"2…Rxd6. White plays 3.Rxd6 and ends up winning a bishop – and the c6 pawn is hanging too."}],"end":"Way 3 to beat a pin: sacrifice your way out. Capture the pinning piece, even if you give up something valuable. Once the pin disappears, the unpinned piece strikes back!"},"unpin4":{"title":"Beating a pin 4: fork the pinner","intro":"Black's bishop on a5 has pinned your c3 knight to your e1 king. You cannot save the knight anymore. Way 4 to beat a pin: set up a fork against the pinning piece. Even the king can make a fork!","moves":[{"q":"The king is lined up with the a5 bishop. Where should it step to get closer to c3?","c":"1.Ke2! The king steps out of the pin. When the bishop takes the knight, the king will attack it. Playing 1.Ra4? Bxc3+ with check, or 1.Rxa5? Nxa5, would give up a rook for a bishop."},{"c":"1…Bxc3. Black captured the knight."},{"q":"The king can attack two black pieces at once. Where should it go?","c":"2.Kd3! A king fork: attacking both the c3 bishop and the c4 knight!"},{"c":"2…Rb4. The rook protects the c4 knight, but not the bishop. White takes 3.Kxc3 and material is equal again."}],"end":"Way 4 to beat a pin: fork the pinner. Sometimes you can't save the pinned piece, but a fork wins a piece right back – and even the king can help!"}}},"endgame":{"name":"Essential Endgames","intro":"Essential endgames: opposition, outflanking, king and pawn, rook pawns, and basic rook endgames.","chapters":{"opp":{"title":"Opposition: who has to step aside","intro":"When only kings are left on the board, the king becomes a fighter. Kings cannot touch each other, so they push each other back. When they stand face-to-face with one, three, or five empty squares between them, the player whose turn it is has to step to the side. That means their opponent has the opposition. Your king wants to reach f8, g8, or h8, and Black's king will try to stop you. First, learn how to keep the opposition.","moves":[{"q":"There are six empty squares between the kings. Step straight toward the black king.","c":"1.Ka2! Now there are five squares between the kings, and it is Black's turn. You have the opposition!"},{"c":"1…Kb8! A clever move. Black stepped aside so the kings wouldn't be on the same file."},{"q":"Step right back in front of him.","c":"2.Kb2. The kings are face-to-face again, and Black has to move aside. If you played 2.Ka3?, Black could pick between two squares on the a-file and take the opposition."},{"c":"2…Kc8. Black moves alongside you to block your path."},{"q":"Keep going right, staying in front of Black's king. Why not straight forward? Because going forward would lose the opposition.","c":"3.Kc2. The opposition is still yours."},{"c":"3…Kd8."},{"q":"Keep moving right.","c":"4.Kd2."},{"c":"4…Ke8."},{"q":"Stay face-to-face with him.","c":"5.Ke2."},{"c":"5…Kf8. Black's king is already near the target squares."},{"q":"A little more to the right.","c":"6.Kf2."},{"c":"6…Kg8."},{"q":"Step onto the g-file, right in the middle between the target squares.","c":"7.Kg2! Your king stands on the g-file, right between the target squares f8 and h8. Now when it moves forward, one of those target squares will always be within reach."},{"c":"7…Kh8. Black's king stepped to the edge. In the next chapter you'll see how to reach the goal."}],"end":"Opposition: when kings face each other with an odd number of squares between them, the player whose turn it is has to step aside. You want that to be your opponent."},"outflank":{"title":"Outflanking: sneaking past the enemy king","intro":"Let's continue. Your king is on g2 and wants to reach f8, g8, or h8. If it only walks straight ahead, Black's king will block the road. Outflanking helps: your king steps diagonally past the opponent's king and gives away the opposition for a moment. Opposition isn't the final goal—it's just a tool. The real goal is moving forward.","moves":[{"q":"Move forward diagonally, not straight ahead.","c":"8.Kf3! The king steps diagonally forward. Black can take the opposition, but your king sneaks farther up the board."},{"c":"8…Kg7. Black comes to meet you."},{"q":"Stand face-to-face with him again.","c":"9.Kg3! You have the opposition again, and you're one rank higher! Moves like 9.Kf4? Kf6 or 9.Kg4? Kg6 would get you stuck."},{"c":"9…Kf7."},{"q":"Go around him on the other side.","c":"10.Kh4! Another outflank, this time along the edge."},{"c":"10…Kg6. Black stepped in front of you."},{"q":"How do you force him to move aside?","c":"11.Kg4. Opposition! Black has to step sideways."},{"c":"11…Kh6."},{"q":"Black stepped to the edge. Slip past him and move forward.","c":"12.Kf5. Your king is already on the 5th rank."},{"c":"12…Kg7."},{"q":"Opposition!","c":"13.Kg5."},{"c":"13…Kf7."},{"q":"Go around him along the edge.","c":"14.Kh6. You're on the 6th rank."},{"c":"14…Kg8."},{"q":"Step right in front of him.","c":"15.Kg6. Black has to move aside again."},{"c":"15…Kf8."},{"q":"One step closer to the goal.","c":"16.Kh7. The h8 square is right there, and Black can no longer guard it."},{"c":"16…Kf7."},{"q":"Reach the goal!","c":"17.Kh8. You made it! In exactly 17 moves."}],"end":"Outflanking: sometimes you have to give your opponent the opposition for a moment so your king can sneak past and move forward. First head toward the side where your goal is, then outflank."},"kpwin":{"title":"King in front of the pawn wins","intro":"You have a king and a pawn against a lone king. You win when your king marches ahead of the pawn and takes control of the promotion square e8. The rule: send your king as far forward as you can and leave the pawn behind. The pawn has spare moves saved up so you can take the opposition whenever you need it. The kings are facing each other and it is Black's turn, so the opposition is yours.","moves":[{"c":"1…Kd5. Black had to step aside."},{"q":"Black stepped to the left. Which do you move, the king or the pawn?","c":"2.Kf4! The king moves forward past the black king. The pawn waits."},{"c":"2…Kd6."},{"q":"Keep moving the king forward!","c":"3.Kf5. Your king is on the 5th rank."},{"c":"3…Ke7."},{"q":"Put your king face-to-face with the black king. Why? So he has to step aside.","c":"4.Ke5. Opposition! Black has to move."},{"c":"4…Kf7."},{"q":"Black stepped aside. Slip past him and move forward.","c":"5.Kd6. Your king is on the 6th rank, close to e8."},{"c":"5…Kf6."},{"q":"Your king is far out in front. Now the pawn can move.","c":"6.e4. The pawn follows the king."},{"c":"6…Kf7."},{"q":"Push the pawn again.","c":"7.e5."},{"c":"7…Ke8."},{"q":"Don't touch the pawn right now! Place your king so Black's king has to move aside.","c":"8.Ke6! Opposition! If you played 8.e6?, then 8…Kd8 gives Black the opposition. Draw."},{"c":"8…Kd8."},{"q":"Claim the square right next to the promotion square.","c":"9.Kf7! Your king guards e8. The pawn will march e6, e7, e8 and turn into a queen."}],"end":"With a king and pawn, you win when your king marches ahead of the pawn. Send the king as far forward as possible, keep the pawn back, and take the opposition at the key moment."},"kpdef":{"title":"Defense: stand in front of the pawn","intro":"Now you are playing Black and you are down a pawn. You can still hold a draw if you guard the promotion square e8. The rule: whenever you can, hop in front of the pawn. When you can't, step straight backward. Then when White's king walks up, step face-to-face with it and the opposition will be yours.","moves":[{"c":"1.Kf2. White's king steps aside to let the pawn move forward."},{"q":"White's king moved away. Where do you step back to stay in front of the pawn?","c":"1…Ke5. You stepped straight back and stayed right in front of the pawn. Watch out for 1…Kd3?? 2.Kf3—your king would no longer be in front of the pawn and White would promote it."},{"c":"2.Kf3."},{"q":"White's king moves forward. Stand face-to-face with it!","c":"2…Kf5. Opposition! White's king cannot get any farther."},{"c":"3.e4+. The pawn gives check."},{"q":"Where now? Hop in front of the pawn!","c":"3…Ke5. You're right back in front of the pawn."},{"c":"4.Ke3. White has the opposition, so Black has to step back."},{"q":"You can't step in front of the pawn right now. Step straight backward!","c":"4…Ke6! Straight back. When White's king walks up, you will step face-to-face with it."},{"c":"5.Kf4."},{"q":"White's king stepped up. What do you do?","c":"5…Kf6! The opposition is yours again."},{"c":"6.e5+."},{"q":"Hop in front of the pawn!","c":"6…Ke6."},{"c":"7.Ke4. White has the opposition."},{"q":"You cannot go forward. Step straight backward.","c":"7…Ke7."},{"c":"8.Kd5. White's king is trying to go around you."},{"q":"Step right in front of him! Which move is it?","c":"8…Kd7! Opposition! After 8…Kf7??, White plays 9.Kd6 and gets in front of the pawn."},{"c":"9.e6+."},{"q":"Hop in front of the pawn.","c":"9…Ke7."},{"c":"10.Ke5. White has the opposition. Here comes the most important move."},{"q":"Step straight backward. Why not to the side? Because White's king would sneak into d6 or f6.","c":"10…Ke8! The only good move. After 10…Kd8?? 11.Kd6 Ke8 12.e7, White's king takes over e8 and wins."},{"c":"11.Kf5. White checks if you'll make a mistake."},{"q":"Hop in front of the pawn!","c":"11…Ke7. Against 11…Kd8?? or 11…Kf8??, White plays 12.Kf6 and wins."},{"c":"12.Ke5."},{"q":"White has the opposition. Where do you step back?","c":"12…Ke8!"},{"c":"13.Kf6."},{"q":"Stand face-to-face with him!","c":"13…Kf8. Opposition."},{"c":"14.e7+."},{"q":"Where must the king go?","c":"14…Ke8. The only legal move."},{"c":"15.Ke6. Stalemate! Black's king has nowhere to move and is not in check. Draw."}],"end":"Defending against a king and pawn: stay in front of the pawn. When you can't, step straight back. When White's king walks up, face it directly. Practice this until you can do it with your eyes closed!"},"rook1":{"title":"Rook pawn: king in the corner","intro":"A rook pawn is a pawn on the a-file or h-file. Different rules apply to it! White's king is standing in front of the pawn, yet White still cannot win. Why? Black's king hides in the corner, and nobody can chase it out. You are playing Black.","moves":[{"c":"1.h4."},{"q":"Where do you go? Stay right by the corner.","c":"1…Kg8. You don't even have another move."},{"c":"2.h5."},{"q":"Go back into the corner.","c":"2…Kh8."},{"c":"3.Kg6."},{"q":"The king has to move aside. Where?","c":"3…Kg8. Only move, and it's all you need."},{"c":"4.h6."},{"q":"Back to the corner!","c":"4…Kh8."},{"c":"5.h7. Stalemate! Black's king has nowhere to move. Draw."}],"end":"You cannot chase a king out of the corner in front of a rook pawn. If your king reaches the corner ahead of your opponent's rook pawn, it's a draw."},"rook2":{"title":"Rook pawn: stalemate with no pieces","intro":"White's king is on h7, right next to the promotion square. Black only has a king, yet can still make a draw! You just have to trap White's king inside the corner so it cannot get out. You are playing Black.","moves":[{"c":"1.h6."},{"q":"Where will you go? Trap White's king in the corner.","c":"1…Kf8. Black's king guards g8 and g7."},{"c":"2.Kh8."},{"q":"White's king is trapped. Stay close to it.","c":"2…Kf7."},{"c":"3.h7."},{"q":"Last move. Where?","c":"3…Kf8. Stalemate! White's king cannot move and neither can the pawn."}],"end":"Against a rook pawn, sometimes all you need is to lock the enemy king in the corner. It can't get out, and the game ends in stalemate."},"lucena":{"title":"The Lucena Position: building a bridge","intro":"Rook endgames happen more often than any other kind. This is the most important one of all. Your b7 pawn is almost ready to promote, but your king is stuck in front of it on b8 and can't get out. If it steps out, Black's rook will give check after check. A trick called building a bridge will save the day.","moves":[{"q":"First push Black's king as far away from the pawn as possible. How?","c":"1.Rd2+! With check, you push Black's king onto the e-file. If it went to c6, your king would step to c8 and win right away."},{"c":"1…Ke7."},{"q":"Place your rook on the 4th rank. Why there? Later you'll use it to block the checks.","c":"2.Rd4! This is how you start building the bridge. If the king walked out right away with 2.Kc7, Black's rook would check it back inside."},{"c":"2…Ke6. Black's king comes back."},{"q":"Now the king can step out.","c":"3.Kc7. The king finally escapes."},{"c":"3…Rc1+. Here come the checks."},{"q":"Step out of check while still protecting your pawn.","c":"4.Kb6."},{"c":"4…Rb1+."},{"q":"Where do you step away?","c":"5.Kc6. If Black kept checking with 5…Rc1+, White plays 6.Kb5 Rb1+ 7.Rb4 and the bridge is ready."},{"c":"5…Rb2. Black stopped checking."},{"q":"Push Black's king even farther away.","c":"6.Re4+! The king has to go even farther from the pawn. Watch out for the trap 6.Rd5?? Rxb7, which is a draw!"},{"c":"6…Kf5."},{"q":"Put your rook on the c-file. Why? To shield your king when it goes to c7.","c":"7.Rc4! The bridge is built! Your king will go to c7, the rook will block the checks, and the pawn will promote."}],"end":"Lucena Position: push the enemy king aside with check, place your rook on the 4th rank, and later block the checks with it. That's called building a bridge."},"passive":{"title":"A passive rook loses","intro":"Black's rook is sitting on the back rank, just waiting. We call that a passive rook. It looks like it's guarding the whole rank, but it isn't. Watch why!","moves":[{"q":"Swing your rook to the other side of Black's king. Where?","c":"1.Ra7! The rook threatens checkmate on a8. Black's g8 rook is too far away to help."},{"c":"1…Kb8. The king attacks your rook."},{"q":"Your rook is attacked. What do you do?","c":"2.c7+! Check! Your king protects the a7 rook, so Black cannot take it."},{"c":"2…Kc8."},{"q":"Give check with the rook.","c":"3.Ra8+. The king has to move, and Black's g8 rook will fall."},{"c":"3…Kd7."},{"q":"Take the rook!","c":"4.Rxg8. White won the rook."}],"end":"A passive rook on the back rank cannot guard everything. When your opponent sneaks around to the other side, it loses. Keep your rook active: attack and give checks!"},"center":{"title":"Center pawn: don't rush","intro":"A similar position, except the pawn is on d6. White wins again if the rook gets to the other side of Black's king. Just don't rush with the pawn! The pawn is a shield for your king.","moves":[{"q":"Just like last time: send the rook to the other side of the king.","c":"1.Ra7! If you played 1.d7+?, then 1…Kd8 stops your rook from reaching the a-file. Draw."},{"c":"1…Kb8. The king attacks the rook."},{"q":"Your rook is attacked. Give check!","c":"2.Rb7+."},{"c":"2…Ka8. On 2…Kc8? White plays 3.d7+."},{"q":"Move the rook far away from Black's king, to a safe square.","c":"3.Rb1. The rook is safe, and Black's king is trapped in the corner."},{"c":"3…Rc8+. Otherwise White plays Kc7, d7, and d8=Q."},{"q":"Step out of check, closer to your pawn.","c":"4.Kd7."},{"c":"4…Rc2."},{"q":"The king marches in front of the pawn.","c":"5.Ke7."},{"c":"5…Re2+."},{"q":"Where do you step out of check?","c":"6.Kd8. Now the king stands in front of the pawn."},{"c":"6…Rd2."},{"q":"Now the pawn can move forward.","c":"7.d7."},{"c":"7…Re2."},{"q":"Put your rook on the 4th rank. Remember the Lucena Position?","c":"8.Rb4! It's the Lucena Position! White will build the bridge and win."}],"end":"Your pawn is a shield for your king. Don't push it until the decisive moment. Get your rook and king ready first."},"philidor":{"title":"The Philidor Defense","intro":"You are playing Black and you are down a pawn. White's king and pawn are far forward, and White's rook is active. It looks bad, but over 200 years ago a master named Philidor showed how to defend it. Your rook will stop White's king on the 6th rank.","moves":[{"q":"Put your rook on the 6th rank. Why there? White's king won't be able to cross it.","c":"1…Rg6! White's king cannot step onto the 6th rank because it would be in check."},{"c":"2.Rh7+."},{"q":"Where should the king go? Stay near the promotion square.","c":"2…Ke8."},{"c":"3.e6. White had to push the pawn because the king couldn't get through."},{"q":"The pawn moved forward. Now send your rook all the way to the back. Why? From there it will give checks.","c":"3…Rg1! White's king no longer has a hiding spot behind the pawn."},{"c":"4.Kd6. White threatens checkmate on h8."},{"q":"Give check!","c":"4…Rd1+."},{"c":"5.Ke5."},{"q":"Another check.","c":"5…Re1+."},{"c":"6.Kd6."},{"q":"And check again!","c":"6…Rd1+. White's king cannot hide from the checks. It's a draw!"}],"end":"Philidor Defense: while White's pawn is still back, keep your rook on the 6th rank. Once the pawn pushes forward, move your rook to the back and give checks."},"trade":{"title":"Should you trade queens?","intro":"White is up a pawn. If you trade queens, you'll reach a rook endgame. Can you defend it? Yes, if you remember the Philidor Defense from the last chapter! You are playing Black.","moves":[{"q":"Offer a queen trade with check.","c":"1…Qd7+."},{"c":"2.Qxd7+. Against 2.Qd6, Black plays 2…Rd1+ 3.Rd4 Rxd4+ 4.Kxd4 Qxd6+ 5.exd6 Kd7 and the pawn endgame is a draw."},{"q":"Take the queen back.","c":"2…Kxd7."},{"c":"3.Rf7+."},{"q":"Where should the king go? In front of the pawn.","c":"3…Ke8."},{"c":"4.Ke6. White's king is on the 6th rank."},{"q":"Get your rook behind White's pawn. Why? From behind it holds the pawn back, and White's king has nowhere to hide.","c":"4…Re1! The rook stands behind the pawn and stops it from moving forward. White's king has no shelter."},{"c":"5.Ra7. White threatens checkmate on a8."},{"q":"Escape the checkmate threat. Which side? The short side.","c":"5…Kf8! The king steps to the short side of the board. That leaves lots of room on the long side for the rook to give side checks."},{"c":"6.Ra8+."},{"q":"Step out of check.","c":"6…Kg7."},{"c":"7.Re8. White blocked the e-file and wants to push the pawn."},{"q":"Swing your rook to the long side. Why? From there it will check from the side.","c":"7…Ra1! When White's king steps out, your rook will give checks from the side. It's a draw!"}],"end":"Before trading pieces, picture what endgame you will get. If you know how to defend it—like with the Philidor Defense—you can trade happily."},"dopp":{"title":"Distant opposition","intro":"You already know king and pawn vs. king. Here Black has the extra pawn and you are defending. The kings are far apart. Opposition still works even from far away: when they stand on the same file with three (or five) empty squares between them, your opponent is forced to move first. This is called distant opposition.","moves":[{"q":"Put your king on the same file as Black's king – with three empty squares between them.","c":"1.Kd1! Between the kings are d2, d3, and d4 – three empty squares. The opposition is yours! Playing 1.Ke2? Ke4 gives Black the opposition."},{"c":"1…Ke4."},{"q":"Black's king stepped aside. Step right back in front of it.","c":"2.Ke2! Now it's direct opposition: one square between the kings, and it's Black's turn."},{"c":"2…Kd4. Black cannot break through. Draw!"}],"end":"Distant opposition: when the kings are far apart, step onto the same file with an odd number of squares between them. When they get close, the opposition will stay yours."},"qvp":{"title":"Queen against a pawn","intro":"Black's e2 pawn is one step from promoting. Even so, your queen can stop it! The plan: use checks and pins to force Black's king to step in front of its own pawn. When the king blocks its own pawn, your king gets time to walk closer.","moves":[{"q":"Attack the e2 pawn with your queen.","c":"1.Qd3! The queen attacks the pawn. Black has to guard it with the king."},{"c":"1…Kf2."},{"q":"Pin the pawn to the black king.","c":"2.Qd2. The pawn is pinned to the king."},{"c":"2…Kf1."},{"q":"Give check to the king.","c":"3.Qf4+."},{"c":"3…Ke1. The king had to step in front of the pawn."},{"q":"The king is standing in front of the pawn. Place your queen so it cannot go to d2 or f2.","c":"4.Qe3. The queen guards both d2 and f2. The king has to step to d1."},{"c":"4…Kd1."},{"q":"Check! Force the king back in front of the pawn.","c":"5.Qd3+."},{"c":"5…Ke1. The king is in front of the pawn again – the pawn cannot move forward."},{"q":"The king is blocking its pawn. Now you have time – bring your own king closer!","c":"6.Ke4! Your king uses the free turn to walk closer. Keep repeating this until your king arrives and wins!"}],"end":"Queen against a pawn: use checks to force the enemy king in front of its pawn, then use that turn to bring your own king closer. Careful: against a pawn on a2, c2, f2, or h2 this might not work – see the next chapter!"},"qvpa":{"title":"Queen against a rook pawn","intro":"Black's pawn is on a2. Against an edge pawn, Black has a sneaky trick: the king goes to the a1 corner, and if the queen traps it there, it's stalemate! You must stop Black's king from reaching the corner.","moves":[{"q":"Put your queen on the long diagonal to guard the a1 corner.","c":"1.Qg7! The queen watches the whole diagonal down to a1. Black's king cannot enter the corner. Checking with 1.Qb5+? would be a mistake: Kc2 2.Qa4+ Kb1 3.Qb3+ Ka1, and if you trap the king it's stalemate."},{"c":"1…Kc2."},{"q":"The king is walking away. Catch the pawn in a trap!","c":"2.Qa1. The queen stands right on the promotion square in front of the pawn. The pawn will fall."}],"end":"Against a rook pawn (a-file or h-file), don't let the enemy king into the corner – or it will escape with stalemate!"},"qvr":{"title":"Queen against a rook: a long-range fork","intro":"Black's h7 rook is far away from its king. The queen can win it with a series of checks that ends in a fork: a check to the king that attacks the rook at the same time. A queen can fork from all the way across the board!","moves":[{"q":"Give check and push the king into the corner.","c":"1.Qe5+! On 1…Kc8, White plays 2.Qe8 checkmate."},{"c":"1…Ka8."},{"q":"Another check – from the other side.","c":"2.Qa1+."},{"c":"2…Kb8."},{"q":"Now look closely: find the check that also attacks the h7 rook!","c":"3.Qb1+!! A check along the b1–h7 diagonal with the rook sitting at the other end. A fork from the opposite corner of the board!"},{"c":"3…Ka7."},{"q":"Take the rook!","c":"4.Qxh7+. The rook falls, and White will soon give checkmate."}],"end":"Against a rook separated from its king, look for a check that also attacks the rook. A queen can fork from all the way across the board!"},"rbehind":{"title":"The rook belongs behind a passed pawn","intro":"Your a7 pawn is almost a queen. Black's a2 rook attacks it from behind and guards the promotion square. Here is a golden rule: the rook belongs BEHIND a passed pawn – both behind your own pawn and behind your opponent's pawn. From behind, it protects the pawn and pushes it forward.","moves":[{"q":"First give check to chase the king away.","c":"1.Rd5+! The check drives Black's king away."},{"c":"1…Kf4."},{"q":"Put your rook behind your pawn – from the other side.","c":"2.Ra5! Your rook stands behind the a7 pawn and protects it. Black's rook can no longer take it, and your king can come help. Playing 1.Kb7? Kf4 2.a8=Q Rxa8 3.Kxa8 g3 would let Black's pawn race through."}],"end":"The rook belongs behind a passed pawn – behind your own to push it forward, and behind your opponent's to hold it back."},"cutoff":{"title":"Cut the king off from the pawn","intro":"A rook and pawn against a rook is usually a draw if the defending king gets in front of the pawn. Black's king is on f8 and wants to reach d8. Stop it!","moves":[{"q":"Put your rook where Black's king cannot cross the e-file.","c":"1.Re1! The rook cuts off Black's king along the e-file. Now it can never reach the pawn. After 1.d6? Ke8, the king gets in front of the pawn and holds a draw."},{"c":"1…Rc2. Now White brings the king and pawn up and wins."}],"end":"In a rook endgame, cut the enemy king off from the pawn – usually by placing your rook on the file next to the pawn."}}}};
const DATEL_EN = {};

function trSrc(s){
  if (!s || typeof s !== "string") return s;
  return s
    .replace(/^zisk figúrky$/i, "win a piece")
    .replace(/Mat 1 ťahom/g, "Mate in 1")
    .replace(/Mat 2 ťahmi/g, "Mate in 2")
    .replace(/Mat 3 ťahmi/g, "Mate in 3")
    .replace(/úloha (\d+)/g, "puzzle $1")
    .replace(/problém /g, "problem ")
    .replace(/cvičenie (\d+)/g, "exercise $1")
    .replace(/súťaž (\d+)/g, "contest $1")
    .replace(/kap\.\s*(\d+)/g, "ch. $1")
    .replace(/kapitola (\d+)/g, "chapter $1")
    .replace(/stupeň/g, "level")
    .replace(/pracovný list/gi, "worksheet")
    .replace(/Dvojitý útok/g, "Double attack")
    .replace(/Väzba/g, "Pin")
    .replace(/Vidlička/g, "Fork")
    .replace(/Odkrytý útok/g, "Discovered attack")
    .replace(/Odkrytý šach/g, "Discovered check")
    .replace(/Dvojitý šach/g, "Double check")
    .replace(/Röntgen/g, "Skewer")
    .replace(/Obrana/g, "Defense")
    .replace(/Koncovka/g, "Endgame")
    .replace(/Dáma/g, "Queen")
    .replace(/Veža/g, "Rook")
    .replace(/Strelec/g, "Bishop")
    .replace(/Jazdec/g, "Knight")
    .replace(/Pešiak/g, "Pawn")
    .replace(/Kráľ/g, "King");
}

let globalsDone = false;
window.I18N_APPLY_CONTENT = function(studiesObj){
  if (!window.I18N || !window.I18N.isEn()) return;
  if (!globalsDone){
    globalsDone = true;
    if (window.OPENING_PLANS && OPENINGS_EN.plans){
      for (const [k, v] of Object.entries(OPENINGS_EN.plans)){
        if (window.OPENING_PLANS[k]) Object.assign(window.OPENING_PLANS[k], v);
      }
    }
    if (Array.isArray(window.OPENING_BOOK) && Array.isArray(OPENINGS_EN.book)){
      for (let i = 0; i < window.OPENING_BOOK.length && i < OPENINGS_EN.book.length; i++){
        window.OPENING_BOOK[i][2] = OPENINGS_EN.book[i];
      }
    }
    if (window.HROZBY){
      for (const arr of Object.values(window.HROZBY)){
        if (Array.isArray(arr)) for (const it of arr) if (it && it.src) it.src = trSrc(it.src);
      }
    }
    for (const [key, list] of Object.entries(DATEL_EN)){
      const arr = window[key];
      if (!Array.isArray(arr)) continue;
      const byId = new Map(list.map(x => [x.id, x]));
      for (const g of arr){
        const tr = byId.get(g.id);
        if (tr){
          if (tr.t) g.t = tr.t;
          if (tr.d) g.d = tr.d;
          if (tr.h1) g.h1 = tr.h1;
        }
        if (Array.isArray(g.items)) for (const it of g.items) if (it && it.s) it.s = trSrc(it.s);
      }
    }
  }
  if (studiesObj){
    for (const [sid, stEn] of Object.entries(STUDIES_EN)){
      const st = studiesObj[sid];
      if (!st) continue;
      st.name = stEn.name;
      st.intro = stEn.intro;
      for (const ch of (st.chapters || [])){
        const ce = stEn.chapters[ch.id];
        if (!ce) continue;
        ch.title = ce.title;
        ch.intro = ce.intro;
        ch.end = ce.end;
        if (Array.isArray(ch.moves) && Array.isArray(ce.moves)){
          for (let i = 0; i < ch.moves.length && i < ce.moves.length; i++){
            if (ce.moves[i].q !== undefined) ch.moves[i].q = ce.moves[i].q;
            if (ce.moves[i].c !== undefined) ch.moves[i].c = ce.moves[i].c;
          }
        }
      }
    }
  }
};
})();
